/**
 * This is the root component.
 * It manages the application state, routing between login and scheduler views,
 * and provides the overall application structure.
 * 
 * The app follows a modular architecture with clear separation of concerns:
 * - Authentication (login/logout)
 * - Scheduling system (calendar, events, navigation)
 * - UI components (reusable, well-documented)
 */

import { LoginPage } from '@/features/auth/components/LoginPage';
import { routes } from './AppRoutes';
import { useAuth } from '@/hooks/useAuth';
import { WorkspaceProvider } from '@/contexts/WorkspaceContext';
import { PasswordResetPage } from '@/features/auth/components/PasswordResetPage';
import { InviteError } from '@/features/auth/components/InviteError';
import { supabase } from '@/lib/supabase';
import { useState, useEffect, useMemo } from 'react';
import { createBrowserRouter, RouterProvider } from 'react-router-dom';
import { VisualEffectHandler } from './components/VisualEffectHandler';
import './App.css';

/**
 * This component serves as the entry point.
 * It conditionally renders either the LoginPage or the Router with authenticated routes.
 */
function App() {
  const {
    isAuthenticated,
    user,
    isLoading,
    error,
    login,
    logout
  } = useAuth();

  const [needsPasswordReset, setNeedsPasswordReset] = useState(false);
  const [urlError, setUrlError] = useState<string | null>(null);

  const router = useMemo(() => createBrowserRouter(routes), []);

  useEffect(() => {
    const hash = window.location.hash;

    if (hash.includes('error=')) {
      setUrlError("Inbjudningsl├ñnken ├ñr ogiltig, har g├Ñtt ut, eller s├Ñ har kontot tagits bort av en administrat├╢r.");
      window.location.hash = '';
    }
    else if (hash.includes('type=invite') || hash.includes('type=recovery')) {
      setNeedsPasswordReset(true);
      localStorage.setItem('pending_invite_path', 'true');
    }

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event) => {
      if (event === 'PASSWORD_RECOVERY') {
        setNeedsPasswordReset(true);
        localStorage.setItem('pending_invite_path', 'true');
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (isAuthenticated && !needsPasswordReset) {
      if (localStorage.getItem('pending_invite_path') === 'true') {
        setNeedsPasswordReset(true);
      }
    }
  }, [isAuthenticated, needsPasswordReset]);

  const handleLogin = async (credentials: { email: string; password: string }) => {
    await login(credentials);
    localStorage.removeItem('pending_invite_path');
  };

  const handleLogout = () => {
    logout();
  };

  return (
    <div className="app-container">
      {urlError ? (
        <InviteError error={urlError} onClose={() => setUrlError(null)} />
      ) : needsPasswordReset ? (
        <PasswordResetPage
          onSuccess={() => {
            localStorage.removeItem('pending_invite_path');
            setNeedsPasswordReset(false);
            window.location.hash = '';
          }}
          onCancel={() => {
            localStorage.removeItem('pending_invite_path');
            setNeedsPasswordReset(false);
            window.location.hash = '';
            handleLogout();
          }}
        />
      ) : isAuthenticated && user ? (
        <WorkspaceProvider>
          <VisualEffectHandler />
          <RouterProvider router={router} />
        </WorkspaceProvider>
      ) : (
        <LoginPage
          onLogin={handleLogin}
          isLoading={isLoading}
          error={error}
        />
      )}
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, Suspense, lazy } from 'react';
import { Navigate, useLocation, Outlet, useNavigate, useMatches } from 'react-router-dom';
import { Sidebar } from './features/scheduler/components/Sidebar';
import { LogOut, Settings, ChevronDown, Loader2, ChevronRight } from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';
import { useTranslation } from 'react-i18next';

const CalendarPage = lazy(() => import('@/features/scheduler/components/CalendarPage').then(module => ({ default: module.CalendarPage })));
const WorkNotesPage = lazy(() => import('@/features/notes/components/WorkNotesPage').then(module => ({ default: module.WorkNotesPage })));
const ClientOverviewPage = lazy(() => import('@/features/assistance/components/ClientOverviewPage').then(module => ({ default: module.ClientOverviewPage })));
const DirectoryPage = lazy(() => import('@/features/directory/components/DirectoryPage').then(module => ({ default: module.DirectoryPage })));
const MessagesPage = lazy(() => import('@/features/messages/components/MessagesPage').then(module => ({ default: module.MessagesPage })));
const TimeManagerPage = lazy(() => import('@/features/time/components/TimeManagerPage').then(module => ({ default: module.TimeManagerPage })));
const SettingsPage = lazy(() => import('@/features/settings/components/SettingsPage').then(module => ({ default: module.SettingsPage })));

import { ClientLayout } from './features/client-portal/components/ClientLayout';
const ClientHomePage = lazy(() => import('./features/client-portal/components/ClientHomePage').then(module => ({ default: module.ClientHomePage })));

const RoleGuard: React.FC<{ children: React.ReactNode, allowedRoles: string[] }> = ({ children, allowedRoles }) => {
  const { user } = useAuth();
  const location = useLocation();
  if (!user) return <Navigate to="/" replace />;
  if (!allowedRoles.includes(user.role)) {
     const fallback = user.role === 'client' ? "/home" : "/schedule";
     if (location.pathname === fallback || location.pathname === fallback + '/') {
       // Prevent infinite redirect loop if fallback is also denied
       return (
         <div className="flex-1 flex flex-col items-center justify-center p-8 bg-background">
           <h2 className="text-2xl font-bold text-destructive mb-2">Access Denied</h2>
           <p className="text-muted-foreground">Your role "{user.role}" does not have permission to view this page.</p>
         </div>
       );
     }
     return <Navigate to={fallback} replace />;
  }
  return <>{children}</>;
};

const AppLayoutWrapper: React.FC = () => {
  const { user } = useAuth();
  if (user?.role === 'client') return <ClientLayout />;
  return <Layout />;
};

const RootRedirect: React.FC = () => {
    const { user } = useAuth();
    if (user?.role === 'client') return <Navigate to="/home" replace />;
    return <Navigate to="/schedule" replace />;
};

export const Layout: React.FC = () => {
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const profileRef = useRef<HTMLDivElement>(null);
  const { user, logout } = useAuth();
  const { t } = useTranslation();
  const location = useLocation();
  const navigate = useNavigate();
  const matches = useMatches();

  const userName = user?.name || '';
  const activeSection = location.pathname.substring(1) || 'schedule';

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
        setIsProfileOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const breadcrumbs = matches
    .filter((match: any) => match.handle && match.handle.breadcrumb)
    .map((match: any) => ({
      label: typeof match.handle.breadcrumb === 'function'
        ? match.handle.breadcrumb(t, match.data)
        : match.handle.breadcrumb,
      path: match.pathname
    }));

  return (
    <div className="h-screen flex bg-background overflow-hidden">
      <Sidebar
        activeSection={activeSection}
        onSectionChange={(path) => navigate(`/${path}`)}
      />
      <div className="flex-1 flex flex-col min-w-0">
        <header className="h-14 bg-sidebar border-b border-border flex items-center justify-between px-4">
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <div className="flex items-center gap-1.5 animate-in fade-in slide-in-from-left-2 duration-200">
              {breadcrumbs.length > 0 ? (
                breadcrumbs.map((bc, idx) => (
                  <React.Fragment key={bc.path}>
                    <span className={idx === breadcrumbs.length - 1 ? "text-foreground font-medium" : "cursor-pointer hover:text-foreground transition-colors"} onClick={() => navigate(bc.path)}>
                      {bc.label}
                    </span>
                    {idx < breadcrumbs.length - 1 && <ChevronRight className="w-3.5 h-3.5 opacity-50" />}
                  </React.Fragment>
                ))
              ) : (
                <span className="text-foreground capitalize font-medium">{activeSection.replace('-', ' ')}</span>
              )}
            </div>
          </div>
          <div className="flex items-center gap-3 relative" ref={profileRef}>
            <div onClick={() => setIsProfileOpen(!isProfileOpen)} className="flex items-center gap-3 pl-3 py-1 cursor-pointer hover:bg-secondary rounded-md transition-colors">
              <div className="text-right hidden md:block">
                <div className="text-foreground text-sm font-medium leading-tight">{userName}</div>
                <div className="text-primary text-[10px] font-bold uppercase tracking-wider">{user?.role === 'platform_admin' ? 'dev' : user?.role || 'admin'}</div>
              </div>
              <div className="w-8 h-8 rounded-full bg-gradient-to-br from-primary to-primary/60 flex items-center justify-center shadow-inner">
                <span className="text-foreground text-sm font-bold">{userName.charAt(0).toUpperCase()}</span>
              </div>
              <ChevronDown className="w-4 h-4 text-muted-foreground" />
            </div>
            {isProfileOpen && (
              <div className="absolute top-12 right-0 w-48 bg-sidebar border border-border rounded-xl shadow-2xl py-2 z-50">
                {(user?.role === 'admin' || user?.role === 'platform_admin') && (
                  <>
                    <button
                      onClick={() => { setIsProfileOpen(false); navigate('/settings'); }}
                      className="w-full flex items-center gap-3 px-4 py-2 text-sm text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors"
                    >
                      <Settings className="w-4 h-4" /> {t('common.settings')}
                    </button>
                    <div className="my-1 border-t border-border"></div>
                  </>
                )}
                <button onClick={logout} className="w-full flex items-center gap-3 px-4 py-2 text-sm text-red-400 hover:text-red-300 hover:bg-red-500/10 transition-colors">
                  <LogOut className="w-4 h-4" /> {t('common.logout')}
                </button>
              </div>
            )}
          </div>
        </header>
        <Suspense fallback={
          <div className="flex-1 flex items-center justify-center bg-background">
            <div className="flex flex-col items-center gap-4 text-muted-foreground animate-pulse">
              <Loader2 className="w-8 h-8 animate-spin text-primary" />
              <span className="text-sm font-medium">{t('common.loading_view')}...</span>
            </div>
          </div>
        }>
          <Outlet />
        </Suspense>
      </div>
    </div>
  );
};

export const routes = [
  {
    path: "/",
    element: <AppLayoutWrapper />,
    children: [
      { index: true, element: <RootRedirect /> },
      {
        path: "home",
        element: <RoleGuard allowedRoles={['client']}><ClientHomePage /></RoleGuard>,
        handle: { breadcrumb: (t: any) => t('common.home', 'Hem') }
      },
      {
        path: "schedule",
        element: <RoleGuard allowedRoles={['platform_admin', 'admin', 'user', 'assistant']}><CalendarPage /></RoleGuard>,
        handle: { breadcrumb: (t: any) => t('sidebar.sections.schedule') }
      },
      {
        path: "inbox",
        element: <RoleGuard allowedRoles={['platform_admin', 'admin', 'user', 'assistant', 'client']}><MessagesPage /></RoleGuard>,
        handle: { breadcrumb: (t: any) => t('sidebar.sections.inbox') }
      },
      {
        path: "directory",
        element: <RoleGuard allowedRoles={['platform_admin', 'admin', 'user', 'assistant']}><DirectoryPage /></RoleGuard>,
        handle: { breadcrumb: (t: any) => t('sidebar.sections.directory') }
      },
      {
        path: "work-notes",
        element: <RoleGuard allowedRoles={['platform_admin', 'admin', 'user', 'assistant']}><WorkNotesPage /></RoleGuard>,
        handle: { breadcrumb: (t: any) => t('sidebar.sections.notes') }
      },
      {
        path: "medication",
        element: <RoleGuard allowedRoles={['platform_admin', 'admin', 'user', 'assistant']}><ClientOverviewPage /></RoleGuard>,
        handle: { breadcrumb: (t: any) => t('sidebar.sections.assistance', 'Assistance') }
      },
      {
        path: "settings",
        element: <RoleGuard allowedRoles={['platform_admin', 'admin']}><SettingsPage /></RoleGuard>,
        handle: { breadcrumb: (t: any) => t('common.settings') }
      },
      {
        path: "time",
        element: <RoleGuard allowedRoles={['platform_admin', 'admin', 'user', 'assistant']}><div className="flex-1 min-w-0 overflow-y-auto"><TimeManagerPage /></div></RoleGuard>,
        handle: { breadcrumb: (t: any) => t('sidebar.sections.time') }
      },
      {
        path: "timereports",
        element: <RoleGuard allowedRoles={['platform_admin', 'admin', 'user', 'assistant']}><div className="flex-1 min-w-0 overflow-y-auto"><TimeManagerPage /></div></RoleGuard>,
        handle: { breadcrumb: (t: any) => t('sidebar.sections.timereports') }
      },
    ]
  }
];

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useWorkspace } from '@/contexts/WorkspaceContext';
import { useWorkspaceUsers, useWorkspaceTeams, useWorkspaceNotes } from '@/hooks/queries/useWorkspaceData';
import { useMessages } from '@/hooks/queries/useMessages';
import {
  CommandDialog,
  CommandInput,
  CommandList,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandSeparator,
} from '@/components/ui/command';
import {
  Users,
  User,
  Calendar,
  Mail,
  FileText,
  Settings,
  Clock,
  LayoutGrid,
  Globe,
  Palette,
  BellRing
} from 'lucide-react';

interface GlobalSearchProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

import { useAuth } from '@/hooks/useAuth';

export const GlobalSearch: React.FC<GlobalSearchProps> = ({ open, onOpenChange }) => {
  const navigate = useNavigate();
  const { t } = useTranslation();
  const { user } = useAuth();
  const { workspaceId } = useWorkspace();

  const { data: users = [] } = useWorkspaceUsers(workspaceId);
  const { data: teams = [] } = useWorkspaceTeams(workspaceId);
  const { data: notes = [] } = useWorkspaceNotes(workspaceId);
  const { data: rawMessages = [] } = useMessages(workspaceId || undefined);

  const messages = React.useMemo(() => {
    return rawMessages.map((m: any) => {
      const sndrData = Array.isArray(m.sender) ? m.sender[0] : m.sender;
      const senderName = sndrData ? (sndrData.full_name || sndrData.email || t('messages.system')) : t('messages.system');
      const isSent = m.sender_id === user?.id;
      
      return {
        id: m.id,
        subject: m.subject || t('messages.no_header'),
        senderName,
        isSent,
        date: new Date(m.created_at).toLocaleDateString()
      };
    });
  }, [rawMessages, user?.id, t]);

  const navigationItems = [
    { id: 'schedule', label: t('sidebar.schedule'), path: '/schedule', icon: Calendar },
    { id: 'inbox', label: t('sidebar.inbox'), path: '/inbox', icon: Mail },
    { id: 'work-notes', label: t('sidebar.work_notes'), path: '/work-notes', icon: FileText },
    { id: 'directory', label: t('sidebar.teams'), path: '/directory', icon: Users },
    { id: 'time', label: t('sidebar.time_management'), path: '/time', icon: Clock },
    { id: 'settings', label: t('common.settings'), path: '/settings', icon: Settings },
  ];

  const settingsItems = [
    { id: 'set-gen', label: t('settings.localization') || 'Spr├Ñk & Tidszon', path: '/settings?tab=general', icon: Globe },
    { id: 'set-app', label: t('settings.theme') || 'Tema & Utseende', path: '/settings?tab=general', icon: Palette },
    { id: 'set-mod', label: t('settings.tabs.modules') || 'Moduler & Funktioner', path: '/settings?tab=modules', icon: LayoutGrid },
    { id: 'set-not', label: t('settings.notifications.title') || 'Notiser', path: '/settings?tab=notifications', icon: BellRing },
  ];

  const onSelect = (path: string) => {
    navigate(path);
    onOpenChange(false);
  };

  return (
    <CommandDialog open={open} onOpenChange={onOpenChange}>
      <CommandInput 
        placeholder={t('common.search') + "..."} 
        className="focus:ring-0 focus-visible:ring-0 shadow-none border-none outline-none"
      />
      <CommandList className="scrollbar-dark">
        <CommandEmpty>{t('messages.empty_state') || 'Hittade ingenting...'}</CommandEmpty>

        <CommandGroup heading={t('sidebar.show') || 'Navigering'}>
          {navigationItems.map((item) => (
            <CommandItem key={item.id} onSelect={() => onSelect(item.path)}>
              <item.icon className="mr-2 h-4 w-4" />
              <span>{item.label}</span>
            </CommandItem>
          ))}
        </CommandGroup>

        <CommandSeparator />

        <CommandGroup heading={t('sidebar.inbox') || 'Inkorg'}>
          {messages.map((msg: { id: string; subject: string; isSent: boolean; senderName: string; date: string }) => (
            <CommandItem key={msg.id} onSelect={() => onSelect(`/inbox?messageId=${msg.id}`)}>
              <Mail className="mr-2 h-4 w-4" />
              <div className="flex flex-col">
                <span className="font-medium">{msg.subject}</span>
                <span className="text-[10px] text-muted-foreground truncate max-w-[400px]">
                  {msg.isSent ? t('messages.sent') : msg.senderName} ΓÇó {msg.date}
                </span>
              </div>
            </CommandItem>
          ))}
        </CommandGroup>

        <CommandSeparator />

        <CommandGroup heading={t('sidebar.work_notes') || 'Arbetspassanteckningar'}>
          {notes.map((note) => (
            <CommandItem key={note.id} onSelect={() => onSelect(`/work-notes?team=${note.team_id}&note=${note.id}`)}>
              <FileText className="mr-2 h-4 w-4" />
              <div className="flex flex-col">
                <span className="font-medium">{note.subject}</span>
                <span className="text-[10px] text-muted-foreground truncate max-w-[400px]">
                  {note.team?.name} ΓÇó {note.author?.full_name || note.author?.email}
                </span>
              </div>
            </CommandItem>
          ))}
        </CommandGroup>

        <CommandSeparator />

        <CommandGroup heading={t('common.settings') || 'Inst├ñllningar'}>
          {settingsItems.map((item) => (
            <CommandItem key={item.id} onSelect={() => onSelect(item.path)}>
              <item.icon className="mr-2 h-4 w-4" />
              <span>{item.label}</span>
            </CommandItem>
          ))}
        </CommandGroup>

        <CommandSeparator />

        <CommandGroup heading={t('directory.levels.teams') || 'Teams'}>
          {teams.map((team) => (
            <CommandItem key={team.id} onSelect={() => onSelect(`/directory?team=${team.id}`)}>
              <LayoutGrid className="mr-2 h-4 w-4" />
              <span>{team.name}</span>
            </CommandItem>
          ))}
        </CommandGroup>

        <CommandSeparator />

        <CommandGroup heading={t('directory.roles.assistant') || 'Personal'}>
          {users.map((user) => (
            <CommandItem key={user.id} onSelect={() => onSelect(`/directory?user=${user.id}`)}>
              <User className="mr-2 h-4 w-4" />
              <div className="flex flex-col">
                <span>{user.name}</span>
                <span className="text-[10px] text-muted-foreground">{user.email}</span>
              </div>
            </CommandItem>
          ))}
        </CommandGroup>
      </CommandList>
    </CommandDialog>
  );
};

import { useEffect } from 'react';
import { useWorkspace } from '@/contexts/WorkspaceContext';

export function VisualEffectHandler() {
  const { preferences } = useWorkspace();

  useEffect(() => {
    if (!preferences?.accent_color) return;

    const root = document.documentElement;
    
    if (preferences.accent_color === 'primary') {
      // Reset to default
      root.style.removeProperty('--primary');
      root.style.removeProperty('--primary-foreground');
      return;
    }

    const hsl = hexToHsl(preferences.accent_color);
    const hslString = `${hsl.h} ${hsl.s}% ${hsl.l}%`;
    const foregroundString = hsl.l > 60 ? '0 0% 0%' : '0 0% 100%';

    root.style.setProperty('--primary', hslString);
    root.style.setProperty('--primary-foreground', foregroundString);
    root.style.setProperty('--ring', hslString);

    // Apply font scale
    if (preferences.font_scale) {
      root.style.fontSize = `${preferences.font_scale * 100}%`;
    } else {
      root.style.fontSize = '100%';
    }

  }, [preferences?.accent_color, preferences?.font_scale]);

  return null;
}

function hexToHsl(hex: string) {
  let r = 0, g = 0, b = 0;
  if (hex.length === 4) {
    r = parseInt(hex[1] + hex[1], 16);
    g = parseInt(hex[2] + hex[2], 16);
    b = parseInt(hex[3] + hex[3], 16);
  } else if (hex.length === 7) {
    r = parseInt(hex[1] + hex[2], 16);
    g = parseInt(hex[3] + hex[4], 16);
    b = parseInt(hex[5] + hex[6], 16);
  }
  r /= 255; g /= 255; b /= 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  let h = 0, s = 0, l = (max + min) / 2;
  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case r: h = (g - b) / d + (g < b ? 6 : 0); break;
      case g: h = (b - r) / d + 2; break;
      case b: h = (r - g) / d + 4; break;
    }
    h /= 6;
  }
  return {
    h: Math.round(h * 360),
    s: Math.round(s * 100),
    l: Math.round(l * 100)
  };
}

import React, { createContext, useContext, useEffect, useState } from "react"

type Theme = "dark" | "light" | "system"

type ThemeProviderProps = {
  children: React.ReactNode
  defaultTheme?: Theme
  storageKey?: string
}

type ThemeProviderState = {
  theme: Theme
  setTheme: (theme: Theme) => void
}

const initialState: ThemeProviderState = {
  theme: "system",
  setTheme: () => null,
}

const ThemeProviderContext = createContext<ThemeProviderState>(initialState)

export function ThemeProvider({
  children,
  defaultTheme = "system",
  storageKey = "vite-ui-theme",
  ...props
}: ThemeProviderProps) {
  const [theme, setTheme] = useState<Theme>(
    () => (localStorage.getItem(storageKey) as Theme) || defaultTheme
  )

  useEffect(() => {
    const root = window.document.documentElement

    root.classList.remove("light", "dark")

    if (theme === "system") {
      const systemTheme = window.matchMedia("(prefers-color-scheme: dark)")
        .matches
        ? "dark"
        : "light"

      root.classList.add(systemTheme)
      return
    }

    root.classList.add(theme)
  }, [theme])

  const value = {
    theme,
    setTheme: (theme: Theme) => {
      localStorage.setItem(storageKey, theme)
      setTheme(theme)
    },
  }

  return (
    <ThemeProviderContext.Provider {...props} value={value}>
      {children}
    </ThemeProviderContext.Provider>
  )
}

export const useTheme = () => {
  const context = useContext(ThemeProviderContext)

  if (context === undefined)
    throw new Error("useTheme must be used within a ThemeProvider")

  return context
}

