import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/lib/supabase';
import { useWorkspace } from '@/contexts/WorkspaceContext';
import { useAuth } from '@/hooks/useAuth';

export type DirectoryLevel = 'workspaces' | 'teams' | 'members';

export interface WorkspaceItem {
  id: string;
  name: string;
  type: string;
  teamsCount: number;
  membersCount: number;
}

export interface TeamItem {
  id: string;
  name: string;
  workspaceId: string;
  membersCount: number;
  patientsCount: number;
  leader: string;
}

export interface MemberItem {
  id: string;
  name: string;
  email: string;
  ssn: string;
  teamId: string | null;
  phone: string;
  address: string;
  careLevel: string;
  avatar: string;
  alerts: string[];
  notes: string;
  upcomingVisits: { id: string; date: string; title: string }[];
  roleId: string | null;
  role: string;
}

interface TeamMemberLink {
  team_id: string;
  user_id: string;
  role_id: string | null;
}

interface UserDbRow {
  id: string;
  full_name: string | null;
  email: string;
  phone: string | null;
  role: string | null;
  workspace_id: string;
}

export interface WorkspaceRole {
  id: string;
  name: string;
  workspace_id: string;
  permissions: {
    can_manage_schedule: boolean;
    can_manage_notes: boolean;
    can_approve_time_reports: boolean;
  };
}

import { useSearchParams } from 'react-router-dom';

export const useDirectoryData = () => {
  const { workspaceId, setAdminWorkspace } = useWorkspace();
  const { user } = useAuth();
  const [searchParams] = useSearchParams();
  const userRole = user?.role as 'platform_admin' | 'admin' | 'assistant' || 'admin';

  const initialTeam = searchParams.get('team');
  const initialUser = searchParams.get('user');

  const [currentLevel, setCurrentLevel] = useState<DirectoryLevel>(
    initialUser || initialTeam ? 'members' : (userRole === 'platform_admin' ? 'workspaces' : 'teams')
  );
  const [selectedWorkspace, setSelectedWorkspace] = useState<string | null>(null);
  const [selectedTeam, setSelectedTeam] = useState<string | null>(initialTeam || (initialUser ? 'all_members' : null));
  const [selectedEntity, setSelectedEntity] = useState<WorkspaceItem | TeamItem | MemberItem | null>(null);

  const [dbWorkspaces, setDbWorkspaces] = useState<WorkspaceItem[]>([]);
  const [dbTeams, setDbTeams] = useState<TeamItem[]>([]);
  const [dbMembers, setDbMembers] = useState<MemberItem[]>([]);
  const [dbWorkspaceRoles, setDbWorkspaceRoles] = useState<WorkspaceRole[]>([]);

  // Effect to handle selection of initial user if provided
  useEffect(() => {
    if (initialUser && dbMembers.length > 0) {
      const target = dbMembers.find(m => m.id === initialUser);
      if (target) setSelectedEntity(target);
    }
  }, [initialUser, dbMembers]);

  useEffect(() => {
    if (userRole === 'platform_admin' && !selectedWorkspace && currentLevel === 'teams') {
      setCurrentLevel('workspaces');
    }
  }, [userRole, selectedWorkspace, currentLevel]);

  const loadDirectory = useCallback(async () => {
    const filterWs = selectedWorkspace || workspaceId;

    if (userRole === 'platform_admin') {
      const { data: wsData } = await supabase.from('workspaces').select('*, teams(count), users(count)');
      if (wsData) {
        setDbWorkspaces(wsData.map(w => ({
          id: w.id,
          name: w.name,
          type: 'Assistance',
          teamsCount: w.teams?.[0]?.count || 0,
          membersCount: w.users?.[0]?.count || 0
        })));
      }
    }

    if (filterWs) {
      const { data: rolesData } = await supabase.from('workspace_roles').select('*').eq('workspace_id', filterWs);
      if (rolesData) setDbWorkspaceRoles(rolesData);

      const { data: teamData } = await supabase.from('teams').select('*').eq('workspace_id', filterWs);
      const { data: allUsers } = await supabase.from('users').select('id, role').eq('workspace_id', filterWs);
      const teamIds = teamData?.map(t => t.id) || [];
      let allMemberships: TeamMemberLink[] = [];
      if (teamIds.length > 0) {
        const { data: memberships } = await supabase.from('team_members').select('team_id, user_id, role_id').in('team_id', teamIds);
        allMemberships = (memberships as TeamMemberLink[]) || [];
      }

      if (teamData) {
        setDbTeams(teamData.map(t => {
          const teamLinks = allMemberships.filter(tm => tm.team_id === t.id);
          const assistantLinks = teamLinks.filter(tm => {
            const u = allUsers?.find(u => u.id === tm.user_id);
            return u && u.role === 'assistant' && !tm.role_id;
          });

          return {
            id: t.id,
            name: t.name,
            workspaceId: t.workspace_id,
            membersCount: assistantLinks.length,
            patientsCount: 0,
            leader: 'Unknown'
          };
        }));
      }
    }

    if (selectedTeam) {
      let memberIds: string[] = [];
      let teamMembersLinkData: TeamMemberLink[] = [];
      if (selectedTeam !== 'all_members') {
        const { data: tmData } = await supabase.from('team_members').select('user_id, role_id').eq('team_id', selectedTeam);
        teamMembersLinkData = (tmData as TeamMemberLink[]) || [];
        memberIds = teamMembersLinkData.map(tm => tm.user_id);
      }

      const { data: usersData } = await supabase.from('users').select('*').eq('workspace_id', filterWs);

      const actualTeamUsers = selectedTeam === 'all_members'
        ? (usersData || [])
        : (usersData || []).filter(u => memberIds.includes(u.id));

      const mappedUsers = actualTeamUsers.map((u: UserDbRow) => {
        let customRoleName: string | null = null;
        let customRoleId: string | null = null;
        if (selectedTeam !== 'all_members') {
          const link = teamMembersLinkData.find(tm => tm.user_id === u.id);
          if (link?.role_id) {
            customRoleId = link.role_id;
            const roleDef = dbWorkspaceRoles.find(r => r.id === customRoleId);
            if (roleDef) customRoleName = roleDef.name;
          }
        }

        return {
          id: u.id,
          name: u.full_name || u.email,
          email: u.email,
          ssn: '',
          teamId: selectedTeam,
          phone: u.phone || '',
          address: '',
          careLevel: '',
          avatar: '',
          alerts: [],
          notes: '',
          upcomingVisits: [],
          roleId: customRoleId,
          role: customRoleName || u.role || 'Assistant'
        };
      });

      setDbMembers(mappedUsers);
    }
  }, [selectedWorkspace, workspaceId, selectedTeam, userRole, dbWorkspaceRoles]);

  useEffect(() => {
    // Call loadDirectory without awaiting to avoid the synchronous-looking call in effect body
    // that the linter might be flagging.
    loadDirectory().catch(console.error);

    const channel = supabase.channel('directory-auto-update')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'workspaces' }, () => { loadDirectory(); })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'teams' }, () => { loadDirectory(); })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'users' }, () => { loadDirectory(); })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'team_members' }, () => { loadDirectory(); })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'workspace_roles' }, () => { loadDirectory(); })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [loadDirectory]);

  const handleSelectWorkspace = (wId: string) => {
    setSelectedWorkspace(wId);
    if (userRole === 'platform_admin' && setAdminWorkspace) {
      setAdminWorkspace(wId);
    }
    setCurrentLevel('teams');
  };

  const handleSelectTeam = (tId: string) => {
    setSelectedTeam(tId);
    setCurrentLevel('members');
  };

  const handleBreadcrumbClick = useCallback((level: DirectoryLevel) => {
    if (level === 'workspaces') {
      setSelectedWorkspace(null);
      setSelectedTeam(null);
      setCurrentLevel('workspaces');
    } else if (level === 'teams') {
      setSelectedTeam(null);
      setCurrentLevel('teams');
    }
  }, []);

  return {
    userRole,
    currentLevel,
    setCurrentLevel,
    selectedWorkspace,
    setSelectedWorkspace,
    selectedTeam,
    setSelectedTeam,
    selectedEntity,
    setSelectedEntity,
    dbWorkspaces,
    setDbWorkspaces,
    dbTeams,
    setDbTeams,
    dbMembers,
    setDbMembers,
    dbWorkspaceRoles,
    setDbWorkspaceRoles,
    handleSelectWorkspace,
    handleSelectTeam,
    handleBreadcrumbClick,
    loadDirectory,
    workspaceId
  };
};

import React, { memo, useCallback } from 'react';
import {
  Inbox,
  Trash2,
  Search,
  Check,
  ChevronLeft,
  ChevronRight,
  MoreHorizontal,
  Clock,
  Archive
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useTranslation } from 'react-i18next';
import { MessageSkeleton } from './MessageSkeleton';
import type { ProcessedMessage } from '../types';

interface MessagesListPaneProps {
  messages: ProcessedMessage[];
  isLoading: boolean;
  filterType: string;
  setFilterType: (val: string) => void;
  searchQuery: string;
  setSearchQuery: (val: string) => void;
  currentPage: number;
  setCurrentPage: React.Dispatch<React.SetStateAction<number>>;
  totalPages: number;
  handleSelectMessage: (id: string) => void;
  handleCompose: () => void;
  selectedMsgs: string[];
  setSelectedMsgs: React.Dispatch<React.SetStateAction<string[]>>;
  handleDeleteSelected: () => void;
}

export const MessagesListPane = memo<MessagesListPaneProps>(({
  messages,
  isLoading,
  filterType,
  setFilterType,
  searchQuery,
  setSearchQuery,
  currentPage,
  setCurrentPage,
  totalPages,
  handleSelectMessage,
  handleCompose,
  selectedMsgs,
  setSelectedMsgs,
  handleDeleteSelected
}) => {
  const { t } = useTranslation();

  const getTitle = useCallback(() => {
    if (filterType === 'inbox') return t('messages.inbox');
    if (filterType === 'unread') return t('messages.unread');
    if (filterType === 'sent') return t('messages.sent');
    if (filterType === 'archive') return t('messages.archive');
    if (filterType === 'trash') return t('messages.trash');
    return t('messages.inbox');
  }, [filterType, t]);

  const isAllSelected = messages.length > 0 && selectedMsgs.length === messages.length;

  const toggleSelectAll = useCallback(() => {
    if (isAllSelected) {
      setSelectedMsgs([]);
    } else {
      setSelectedMsgs(messages.map(m => m.id));
    }
  }, [isAllSelected, messages, setSelectedMsgs]);

  const toggleSelect = useCallback((id: string, e: React.MouseEvent<HTMLDivElement>) => {
    e.stopPropagation();
    if (selectedMsgs.includes(id)) {
      setSelectedMsgs(prev => prev.filter(m => m !== id));
    } else {
      setSelectedMsgs(prev => [...prev, id]);
    }
  }, [selectedMsgs, setSelectedMsgs]);

  return (
    <div className="flex-1 flex flex-col h-full bg-background relative selection:bg-primary/20">
      {/* Top Header Controls */}
      <div className="h-16 px-8 flex items-center justify-between border-b border-border/50 bg-background/50 backdrop-blur-md sticky top-0 z-20">
        <div className="flex items-center gap-4">
          <div
            className={`w-8 shrink-0 flex items-center justify-center cursor-pointer group transition-all duration-200 ${isAllSelected ? 'scale-110' : ''}`}
            onClick={toggleSelectAll}
            role="checkbox"
            aria-checked={isAllSelected}
            aria-label={t('common.select_all')}
            tabIndex={0}
            onKeyDown={(e) => { if (e.key === 'Enter') toggleSelectAll() }}
          >
            <div className={`w-4 h-4 rounded-[4px] border ${isAllSelected ? 'border-primary bg-primary' : 'border-border group-hover:border-primary/50'} flex items-center justify-center transition-all duration-300`}>
              {isAllSelected && <Check className="w-3 h-3 text-white" />}
            </div>
          </div>

          <h2 className="text-foreground font-semibold flex items-center ml-2 mr-2 text-lg tracking-tight">
            {getTitle()}
          </h2>

          <Button variant="ghost" size="icon" className="w-8 h-8 rounded-full" aria-label={t('common.more_options')}>
            <MoreHorizontal className="w-4 h-4 text-muted-foreground cursor-pointer hover:text-foreground transition-colors" />
          </Button>

          {selectedMsgs.length > 0 && (
            <div className="flex items-center gap-1 border-l border-border ml-2 pl-4 animate-in fade-in slide-in-from-left-2 duration-300">
              <Button variant="ghost" size="icon" aria-label={t('messages.delete_selected')} className="w-8 h-8 text-muted-foreground hover:text-rose-400 hover:bg-rose-500/10 transition-all" onClick={handleDeleteSelected}>
                <Trash2 className="w-4 h-4" />
              </Button>
              <div className="text-[10px] bg-primary/10 text-primary px-2.5 py-0.5 rounded-full font-bold ml-1 border border-primary/20">
                {selectedMsgs.length} {t('messages.selected')}
              </div>
            </div>
          )}
        </div>

        <div className="flex items-center gap-6">
          <div className="relative w-64 group">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground group-focus-within:text-primary transition-colors" />
            <Input
              placeholder={t('messages.search_placeholder')}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              aria-label={t('messages.search_placeholder')}
              className="pl-9 bg-muted/50 border border-border/50 text-foreground h-9 rounded-full text-xs focus-visible:ring-1 focus-visible:ring-primary focus-visible:bg-muted transition-all"
            />
          </div>

          <div className="flex items-center gap-1 text-xs text-muted-foreground relative group">
            <select
              value={filterType}
              onChange={(e) => setFilterType(e.target.value)}
              aria-label={t('messages.filter')}
              className="bg-muted/80 border border-border/50 text-foreground font-semibold hover:bg-secondary cursor-pointer rounded-lg pl-3 pr-8 py-1.5 appearance-none focus:outline-none focus:border-primary/50 focus:ring-1 focus:ring-primary/20 transition-all"
              style={{ WebkitAppearance: 'none' }}
            >
              <option value="inbox" className="bg-card text-foreground py-2">{t('messages.inbox')}</option>
              <option value="unread" className="bg-card text-foreground py-2">{t('messages.unread')}</option>
              <option value="sent" className="bg-card text-foreground py-2">{t('messages.sent')}</option>
              <option value="archive" className="bg-card text-foreground py-2">{t('messages.archive')}</option>
              <option value="trash" className="bg-card text-rose-400 py-2">{t('messages.trash')}</option>
            </select>
            <div className="pointer-events-none absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground group-hover:text-foreground transition-colors">
              <ChevronLeft className="w-3.5 h-3.5 -rotate-90" />
            </div>
          </div>

          <div className="flex items-center gap-3 text-muted-foreground">
            <Button
              variant="ghost"
              size="icon"
              aria-label={t('pagination.previous')}
              className={`w-8 h-8 rounded-full transition-all ${currentPage > 1 ? 'hover:text-foreground hover:bg-secondary' : 'opacity-30'}`}
              disabled={currentPage <= 1 || isLoading}
              onClick={() => setCurrentPage(prev => prev - 1)}
            >
              <ChevronLeft className="w-4 h-4" />
            </Button>
            <span className="text-xs font-bold tabular-nums text-foreground/80" aria-label={t('pagination.page_info', { current: currentPage, total: totalPages })}>{currentPage} <span className="text-muted-foreground font-medium mx-1">/</span> {totalPages}</span>
            <Button
              variant="ghost"
              size="icon"
              aria-label={t('pagination.next')}
              className={`w-8 h-8 rounded-full transition-all ${currentPage < totalPages ? 'hover:text-foreground hover:bg-secondary' : 'opacity-30'}`}
              disabled={currentPage >= totalPages || isLoading}
              onClick={() => setCurrentPage(prev => prev + 1)}
            >
              <ChevronRight className="w-4 h-4" />
            </Button>
          </div>
        </div>
      </div>

      {isLoading ? (
        <MessageSkeleton />
      ) : (
        <div className="flex-1 overflow-y-auto w-full scrollbar-dark scroll-smooth">
          {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-muted-foreground animate-in fade-in zoom-in-95 duration-500">
              <div className="w-20 h-20 bg-muted/30 rounded-full flex items-center justify-center mb-6 border border-border/50">
                <Inbox className="w-10 h-10 opacity-20" />
              </div>
              <p className="text-sm font-medium">{t('messages.empty_state')}</p>
            </div>
          ) : (
            <div className="flex flex-col w-full text-sm">
              {messages.map((msg, idx) => {
                const isSelected = selectedMsgs.includes(msg.id);
                return (
                  <div
                    key={msg.id}
                    onClick={() => handleSelectMessage(msg.id)}
                    className={`group flex items-center px-6 py-3.5 border-b border-border/40 hover:bg-secondary/40 cursor-pointer transition-all duration-300 animate-in fade-in slide-in-from-bottom-2 fill-mode-both`}
                    style={{ animationDelay: `${idx * 30}ms` }}
                    tabIndex={0}
                    onKeyDown={(e) => { if (e.key === 'Enter') handleSelectMessage(msg.id) }}
                    aria-label={t('messages.read_message', { subject: msg.subject })}
                  >
                    <div
                      className="w-10 shrink-0 flex items-center justify-start py-1"
                      onClick={(e) => toggleSelect(msg.id, e)}
                      role="checkbox"
                      aria-checked={isSelected}
                      aria-label={t('messages.select_message')}
                      tabIndex={0}
                      onKeyDown={(e) => { if (e.key === 'Enter') toggleSelect(msg.id, e as any) }}
                    >
                      <div className={`w-[18px] h-[18px] rounded-[5px] border transition-all duration-300 ${isSelected ? 'border-primary bg-primary' : 'border-border/60 group-hover:border-primary/50'}`}>
                        {isSelected && <Check className="w-3.5 h-3.5 text-white" />}
                      </div>
                    </div>

                    <div className={`w-56 shrink-0 truncate pr-4 transition-colors ${msg.unread ? 'text-foreground font-bold' : 'text-muted-foreground group-hover:text-foreground/80'}`}>
                      <div className="flex items-center gap-2">
                        {msg.sender.name}
                        {msg.unread && <span className="w-1.5 h-1.5 rounded-full bg-primary" />}
                      </div>
                      {msg.isTeamMessage && msg.folderId !== 'sent' && (
                        <div className="text-[10px] uppercase font-bold text-primary mt-1 tracking-widest truncate opacity-80">
                          {t('messages.team_collective', { name: msg.to })}
                        </div>
                      )}
                    </div>

                    <div className="flex-1 flex items-center truncate min-w-0 pr-6 gap-x-2">
                      {msg.folderId === 'sent' && <span className="text-[10px] font-black uppercase tracking-tighter text-primary/60 bg-primary/5 px-1.5 py-0.5 rounded shrink-0">{t('messages.to')} {msg.to}</span>}
                      <span className={`${msg.unread ? 'text-foreground font-bold' : 'text-foreground/90'} truncate`}>
                        {msg.subject}
                      </span>
                      <span className="text-muted-foreground/60 truncate italic font-light">
                        {msg.snippet}
                      </span>
                    </div>

                    <div className="w-48 shrink-0 flex items-center justify-end">
                      <div className="opacity-0 group-hover:opacity-100 flex items-center gap-3.5 mr-6 text-muted-foreground/60 transition-all duration-300 translate-x-2 group-hover:translate-x-0">
                        <Archive className="w-[18px] h-[18px] hover:text-primary transition-colors cursor-pointer" />
                        <Trash2 className="w-[18px] h-[18px] hover:text-rose-500 transition-colors cursor-pointer" />
                        <Clock className="w-[18px] h-[18px] hover:text-foreground transition-colors cursor-pointer" />
                      </div>
                      <span className={`text-[11px] font-bold tracking-tighter uppercase tabular-nums ${msg.unread ? 'text-primary' : 'text-muted-foreground/50'}`}>
                        {msg.date === t('common.today') ? msg.timestamp : msg.date}
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Floating Action Button */}
      <div className="absolute bottom-10 right-10 z-20">
        <Button
          onClick={handleCompose}
          size="lg"
          aria-label={t('messages.new_message')}
          className="rounded-full h-14 pl-5 pr-7 bg-foreground text-background hover:bg-foreground/90 shadow-[0_20px_50px_rgba(0,0,0,0.3)] font-bold flex items-center gap-2.5 transition-all hover:scale-105 active:scale-95 group overflow-hidden"
        >
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <path d="M12 5v14M5 12h14" />
          </svg>
          <span className="relative z-10">{t('messages.new_message')}</span>
        </Button>
      </div>
    </div>
  );
});

MessagesListPane.displayName = 'MessagesListPane';

import React, { useMemo, useCallback } from 'react';
import { useWorkspace } from '@/contexts/WorkspaceContext';
import { useAuth } from '@/hooks/useAuth';
import { useTranslation } from 'react-i18next';
import { useMessages, useMarkMessageAsRead, useSendMessage, useDeleteMessages } from '@/hooks/queries/useMessages';
import { useWorkspaceTeams, useWorkspaceUsers } from '@/hooks/queries/useWorkspaceData';
import { toast } from 'sonner';
import { useQueryClient } from '@tanstack/react-query';
import { queryKeys } from '@/lib/query-keys';

import { MessagesListPane } from './MessagesListPane';
import { MessageReadPane } from './MessageReadPane';
import { MessageComposePane } from './MessageComposePane';
import { useMessagesState } from '../hooks/useMessagesState';
import { transformMessages } from '../utils/messageTransformers';
import { useSearchParams } from 'react-router-dom';
import type { Message } from '@/types';

interface MessagePayload {
  workspace_id: string;
  sender_id: string;
  receiver_id?: string;
  target_team_id?: string;
  subject: string;
  body: string;
  is_read: false;
}

export const MessagesPage: React.FC = () => {
  const { workspaceId } = useWorkspace();
  const { user } = useAuth();
  const { t } = useTranslation();
  const [searchParams] = useSearchParams();

  const queryClient = useQueryClient();
  const deleteTimeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);

  const { data: teams = [] } = useWorkspaceTeams(workspaceId || null);
  const { data: users = [] } = useWorkspaceUsers(workspaceId || null);

  const { data: processedMessages = [], isLoading: isLoadingMessages } = useMessages(workspaceId || undefined, {
    select: (data) => transformMessages(data, teams, user, t)
  });

  const markAsReadMutation = useMarkMessageAsRead(workspaceId || undefined);
  const sendMessageMutation = useSendMessage(workspaceId || undefined);
  const deleteMessagesMutation = useDeleteMessages(workspaceId || undefined);

  const [clientData, setClientData] = React.useState<any>(null);
  const [teamMembers, setTeamMembers] = React.useState<string[]>([]);
  const [currentUserTeams, setCurrentUserTeams] = React.useState<string[]>([]);
  const [accessibleColleagues, setAccessibleColleagues] = React.useState<string[]>([]);

  const [allClients, setAllClients] = React.useState<any[]>([]);

  React.useEffect(() => {
    const fetchRelations = async () => {
      // 1. Fetch all clients so assistants can evaluate permissions
      const { data: clientsData } = await supabase.from('clients').select('*');
      if (clientsData) setAllClients(clientsData);

      // 2. Client logic
      if (user?.role === 'client') {
         const { data: userData } = await supabase.from('users').select('client_id').eq('id', user.id).single();
         if (userData?.client_id) {
             const { data: client } = await supabase.from('clients').select('*').eq('id', userData.client_id).single();
             if (client) {
                 setClientData(client);
                 if (client.team_id) {
                     const { data: tm } = await supabase.from('team_members').select('user_id').eq('team_id', client.team_id);
                     if (tm) setTeamMembers(tm.map((t: any) => t.user_id));
                 }
             }
         }
      } 
      // 3. Assistant logic
      else if (user?.role === 'assistant') {
         const { data: myTeams } = await supabase.from('team_members').select('team_id').eq('user_id', user.id);
         if (myTeams && myTeams.length > 0) {
            const teamIds = myTeams.map((t: any) => t.team_id);
            setCurrentUserTeams(teamIds);
            
            const { data: colleagues } = await supabase.from('team_members').select('user_id').in('team_id', teamIds);
            if (colleagues) {
              setAccessibleColleagues(Array.from(new Set(colleagues.map(c => c.user_id))));
            }
         }
      }
    };
    fetchRelations();
  }, [user]);

  const availableUsers = React.useMemo(() => {
     // Admin / Platform Admin can contact everyone
     if (user?.role === 'admin' || user?.role === 'platform_admin') return users;
     
     // Assistant: restricted to own teams and admins + OPEN clients
     if (user?.role === 'assistant') {
       return users.filter(u => {
         if (u.role === 'admin' || u.role === 'platform_admin') return true;
         if (accessibleColleagues.includes(u.id)) return true;
         
         if (u.role === 'client' && u.client_id) {
            const c = allClients.find(c => c.id === u.client_id);
            if (c) {
               const mode = c.message_settings?.allowed_contacts;
               if (mode === 'open' && currentUserTeams.includes(c.team_id)) return true;
               if (mode === 'contact_person' && c.message_settings?.contact_person_email?.toLowerCase() === user.email?.toLowerCase()) return true;
            }
         }
         return false;
       });
     }

     // Client: restricted to admins, contact person, and team
     if (user?.role === 'client') {
       if (!clientData) return [];
       
       const mode = clientData.message_settings?.allowed_contacts || 'admin_only';
       const contactPersonEmail = clientData.message_settings?.contact_person_email?.toLowerCase();
       
       return users.filter(u => {
          if (u.role === 'admin' || u.role === 'platform_admin') return true;
          
          if (mode === 'contact_person' || mode === 'open') {
             if (contactPersonEmail && u.email.toLowerCase() === contactPersonEmail) return true;
          }
          
          if (mode === 'open') {
             if (teamMembers.includes(u.id)) return true;
          }
          return false;
       });
     }

     return [];
  }, [users, user, clientData, teamMembers, accessibleColleagues, allClients, currentUserTeams]);

  const availableTeams = React.useMemo(() => {
     // Admin / Platform Admin can contact all teams
     if (user?.role === 'admin' || user?.role === 'platform_admin') return teams;
     
     // Assistant: can only group-chat their own teams
     if (user?.role === 'assistant') {
       return teams.filter(t => currentUserTeams.includes(t.id));
     }

     // Client: can only group-chat their own assigned team IF they are in 'open' mode
     if (user?.role === 'client') {
       if (!clientData || !clientData.team_id) return [];
       
       const mode = clientData.message_settings?.allowed_contacts;
       if (mode === 'open') {
         return teams.filter(t => t.id === clientData.team_id);
       }
       return [];
     }
     
     return [];
  }, [teams, user, clientData, currentUserTeams]);


  const {
    filterType, setFilterType,
    activeMessageId, setActiveMessageId,
    searchQuery, setSearchQuery,
    currentPage, setCurrentPage,
    selectedMsgs, setSelectedMsgs,
    isComposing, setIsComposing,
    composeData, setComposeData,
    activeMessage
  } = useMessagesState(processedMessages);

  // Handle deep-linking from search params
  React.useEffect(() => {
    const messageId = searchParams.get('messageId');
    if (messageId && processedMessages.length > 0) {
      const msg = processedMessages.find(m => m.id === messageId);
      if (msg) {
        setIsComposing(false);
        setActiveMessageId(messageId);
        if (msg.unread) {
          markAsReadMutation.mutate(messageId);
        }
      }
    }
  }, [searchParams, processedMessages.length, setIsComposing, setActiveMessageId, processedMessages, markAsReadMutation]);

  const { selectedTeamId } = useWorkspace();

  const filteredMessages = useMemo(() => {
    return processedMessages.filter(m => {
      if (selectedTeamId) {
        // If viewing a specific team, show messages to that team OR personal inbox/sent items?
        // Let's stick to only showing items related to that team if filter is active.
        if (m.target_team_id !== selectedTeamId) return false;
      }

      const searchMatch = m.subject.toLowerCase().includes(searchQuery.toLowerCase()) ||
        m.sender.name.toLowerCase().includes(searchQuery.toLowerCase());

      if (!searchMatch) return false;

      if (filterType === 'inbox') return m.folderId === 'inbox';
      if (filterType === 'unread') return m.folderId === 'inbox' && m.unread === true;
      if (filterType === 'sent') return m.folderId === 'sent';
      if (filterType === 'archive') return m.folderId === 'archive';
      if (filterType === 'trash') return m.folderId === 'trash';

      return false;
    });
  }, [processedMessages, filterType, searchQuery, selectedTeamId]);

  const itemsPerPage = 10;
  const totalPages = Math.max(1, Math.ceil(filteredMessages.length / itemsPerPage));
  const currentMessages = filteredMessages.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  React.useEffect(() => {
    setCurrentPage(1);
  }, [filterType, searchQuery, setCurrentPage]);

  const handleSelectMessage = useCallback((id: string) => {
    setIsComposing(false);
    setActiveMessageId(id);
    const msg = processedMessages.find(m => m.id === id);
    if (msg && msg.unread) {
      markAsReadMutation.mutate(id);
    }
  }, [processedMessages, setIsComposing, setActiveMessageId, markAsReadMutation]);

  const handleCompose = useCallback(() => {
    setActiveMessageId(null);
    setComposeData({ targetType: 'user', targetId: '', subject: '', content: '', quote: null });
    setIsComposing(true);
  }, [setActiveMessageId, setComposeData, setIsComposing]);

  const handleSendMessage = useCallback(() => {
    if (!workspaceId || !user || !composeData.targetId || !composeData.content) {
      toast.error(t('messages.fill_required_fields'));
      return;
    }

    const payload: MessagePayload = {
      workspace_id: workspaceId,
      sender_id: user.id,
      subject: composeData.subject || t('messages.no_header'),
      body: composeData.content,
      is_read: false
    };

    if (composeData.targetType === 'user') {
      payload.receiver_id = composeData.targetId;
    } else {
      payload.target_team_id = composeData.targetId;
    }

    sendMessageMutation.mutate(payload, {
      onSuccess: () => {
        setIsComposing(false);
        toast.success(t('messages.message_sent'));
      },
      onError: (error) => {
        toast.error(t('messages.error_sending') + ": " + error.message);
      }
    });
  }, [workspaceId, user, composeData, t, sendMessageMutation, setIsComposing]);

  const handleDeleteSelected = useCallback(() => {
    if (selectedMsgs.length === 0) return;

    const msgsToDelete = [...selectedMsgs];
    const queryKey = queryKeys.messages(workspaceId || undefined);

    // Snapshot the current data
    const previousMessages = queryClient.getQueryData(queryKey);

    // Optimistically update the cache
    queryClient.setQueryData(queryKey, (old: Message[] = []) =>
      old.filter(m => !msgsToDelete.includes(m.id))
    );

    setSelectedMsgs([]);

    // Clear any existing timeout
    if (deleteTimeoutRef.current) {
      clearTimeout(deleteTimeoutRef.current);
    }

    toast.success(t('messages.messages_deleted'), {
      duration: 5000,
      action: {
        label: t('common.undo') || '├àngra',
        onClick: () => {
          if (deleteTimeoutRef.current) {
            clearTimeout(deleteTimeoutRef.current);
            deleteTimeoutRef.current = null;
          }
          // Restore the cache
          queryClient.setQueryData(queryKey, previousMessages);
          toast.dismiss();
          toast.info(t('messages.undo_successful') || "Radering ├Ñngrad");
        }
      }
    });

    // Delay the actual mutation
    deleteTimeoutRef.current = setTimeout(() => {
      deleteMessagesMutation.mutate(msgsToDelete, {
        onError: (error) => {
          toast.error(t('messages.error_deleting') + ": " + error.message);
          // Rollback on error if not already undone
          queryClient.setQueryData(queryKey, previousMessages);
        }
      });
      deleteTimeoutRef.current = null;
    }, 5000);

  }, [workspaceId, queryClient, selectedMsgs, setSelectedMsgs, t, deleteMessagesMutation]);

  const handleReply = useCallback(() => {
    if (activeMessage) {
      setComposeData({
        targetType: activeMessage.isTeamMessage ? 'team' : 'user',
        targetId: activeMessage.sender_id,
        subject: activeMessage.subject.startsWith('Svar:') ? activeMessage.subject : `Svar: ${activeMessage.subject}`,
        content: '',
        quote: {
          type: 'reply',
          sender: activeMessage.sender.name,
          date: activeMessage.date,
          timestamp: activeMessage.timestamp,
          subject: activeMessage.subject,
          content: activeMessage.content
        }
      });
      setActiveMessageId(null);
      setIsComposing(true);
    }
  }, [activeMessage, setComposeData, setActiveMessageId, setIsComposing]);

  const handleForward = useCallback(() => {
    if (activeMessage) {
      setComposeData({
        targetType: 'user',
        targetId: '',
        subject: activeMessage.subject.startsWith('VB:') ? activeMessage.subject : `VB: ${activeMessage.subject}`,
        content: '',
        quote: {
          type: 'forward',
          sender: activeMessage.sender.name,
          date: activeMessage.date,
          timestamp: activeMessage.timestamp,
          subject: activeMessage.subject,
          content: activeMessage.content
        }
      });
      setActiveMessageId(null);
      setIsComposing(true);
    }
  }, [activeMessage, setComposeData, setActiveMessageId, setIsComposing]);

  if (isComposing) {
    return (
      <MessageComposePane
        composeData={composeData}
        setComposeData={setComposeData}
        isSending={sendMessageMutation.isPending}
        handleSendMessage={handleSendMessage}
        setIsComposing={setIsComposing}
        users={availableUsers}
        teams={availableTeams}
        currentUserId={user?.id}
      />
    );
  }

  if (activeMessageId && activeMessage) {
    return (
      <MessageReadPane
        activeMessage={activeMessage}
        currentUserId={user?.id}
        setActiveMessageId={setActiveMessageId}
        handleReply={handleReply}
        handleForward={handleForward}
      />
    );
  }

  return (
    <MessagesListPane
      messages={currentMessages}
      isLoading={isLoadingMessages}
      filterType={filterType}
      setFilterType={setFilterType}
      searchQuery={searchQuery}
      setSearchQuery={setSearchQuery}
      currentPage={currentPage}
      setCurrentPage={setCurrentPage}
      totalPages={totalPages}
      handleSelectMessage={handleSelectMessage}
      handleCompose={handleCompose}
      selectedMsgs={selectedMsgs}
      setSelectedMsgs={setSelectedMsgs}
      handleDeleteSelected={handleDeleteSelected}
    />
  );
};

/**
 * This is the main calendar/scheduler view component with support for
 * multiple view modes: Day, Week, Month, and Agenda.
 * 
 * Each view mode provides a different perspective on the scheduled events,
 * allowing users to choose the most appropriate view for their needs.
 */

import React, { useMemo, useRef, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useWorkspace } from '@/contexts/WorkspaceContext';
import {
  ChevronLeft,
  ChevronRight,
  Calendar as CalendarIcon,
  MapPin
} from 'lucide-react';
import { cn } from '@/lib/utils';
import {
  formatTimeRange,
  generateTimeSlots,
  generateWeekDays,
  getStartOfWeek,
  isToday,
  isSameDay,
  getCategoryConfig,
  calculateEventTop,
  calculateEventHeight,
  formatMonthYear
} from '@/lib/utils';
import type { CalendarEvent, CalendarView as ViewType, User } from '@/types';

const VIEW_MODES: { id: ViewType; label: string }[] = [
  { id: 'day', label: 'Day' },
  { id: 'week', label: 'Week' },
  { id: 'month', label: 'Month' },
  { id: 'agenda', label: 'Agenda' },
];

/**
 * Event Card Component for Day/Week views
 * Displays a single event in the calendar grid with absolute positioning
 */
interface EventCardProps {
  event: CalendarEvent;
  onClick: () => void;
  hourHeight?: number;
  startHour?: number;
  locale?: string;
  tooltipPosition?: 'side' | 'top';
  currentDate: Date;
  users?: User[];
}

const EventCard: React.FC<EventCardProps> = ({
  event,
  onClick,
  hourHeight = 60,
  startHour = 0,
  locale = 'en-US',
  tooltipPosition = 'side',
  currentDate,
  users = []
}) => {
  const categoryConfig = getCategoryConfig(event.category);

  // Helper to format assignee name
  const getDisplayName = () => {
    if (!event.assigneeId) return event.title;
    const user = users.find(u => u.id === event.assigneeId);
    if (!user) return event.title;

    const fullName = user.name || (user as any).full_name || '';
    if (!fullName) return event.title;

    const parts = fullName.trim().split(/\s+/);
    const firstName = parts[0];
    if (parts.length === 1) return firstName;

    const lastName = parts[parts.length - 1];
    // If "First Last" is longer than 12 chars, use "First L."
    if (`${firstName} ${lastName}`.length > 12) {
      return `${firstName} ${lastName.charAt(0)}.`;
    }
    return `${firstName} ${lastName}`;
  };

  const displayName = getDisplayName();

  const dayStart = new Date(currentDate);
  dayStart.setHours(0, 0, 0, 0);
  const dayEnd = new Date(currentDate);
  dayEnd.setHours(23, 59, 59, 999);

  const effectiveStart = event.startTime < dayStart ? dayStart : event.startTime;
  const effectiveEnd = event.endTime > dayEnd ? dayEnd : event.endTime;

  const top = calculateEventTop(effectiveStart, hourHeight, startHour);
  const height = calculateEventHeight(effectiveStart, effectiveEnd, hourHeight);

  return (
    <div
      onClick={onClick}
      className="group absolute left-1 right-1 rounded-md px-2 py-1.5 cursor-pointer
                 transition-all duration-200 hover:brightness-105 hover:shadow-xl
                 text-xs z-10 hover:z-50"
      style={{
        top: `${top}px`,
        height: `${Math.max(height - 2, 24)}px`,
        backgroundColor: categoryConfig.bgColor,
        borderLeft: `3px solid ${categoryConfig.color}`,
      }}
    >
      {/* Event title */}
      <div
        style={{ color: categoryConfig.color }}
      >
        {displayName}
      </div>

      {/* Event time (only show if height allows) */}
      {height > 35 && (
        <div className="text-muted-foreground text-[10px] mt-0.5">
          {formatTimeRange(event.startTime, event.endTime, locale)}
        </div>
      )}

      {/* Event location (only show if height allows) */}
      {height > 50 && event.location && (
        <div className="flex items-center gap-1 text-muted-foreground text-[10px] mt-0.5">
          <MapPin className="w-3 h-3" />
          <span className="truncate">{event.location}</span>
        </div>
      )}

      {/* Hover Information Popup */}
      <div className={cn(
        "hidden group-hover:block absolute w-64 p-4",
        "bg-background/95 backdrop-blur-md border border-border rounded-xl shadow-2xl z-[100]",
        "pointer-events-none animate-in fade-in duration-200",
        tooltipPosition === 'top'
          ? "bottom-full left-1/2 -translate-x-1/2 mb-2 slide-in-from-bottom-2"
          : "left-full top-0 ml-2 zoom-in-95"
      )}>
        <div className="flex items-center justify-between mb-2">
          <span
            className="px-2 py-0.5 rounded text-[10px] uppercase font-bold tracking-wider"
            style={{ backgroundColor: categoryConfig.bgColor, color: categoryConfig.color }}
          >
            {categoryConfig.label}
          </span>
          <span className="text-[10px] text-muted-foreground flex items-center gap-1">
            <CalendarIcon className="w-3 h-3" />
            {event.startTime.toLocaleDateString(locale, { month: 'short', day: 'numeric' })}
          </span>
        </div>

        <h4 className="text-sm font-bold text-foreground mb-1 leading-tight">{event.title}</h4>

        <div className="text-xs text-muted-foreground mb-3 flex flex-col gap-1">
          <div className="flex items-center gap-1.5">
            <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: categoryConfig.color }} />
            {formatTimeRange(event.startTime, event.endTime, locale)}
          </div>
          {event.location && (
            <div className="flex items-center gap-1.5">
              <MapPin className="w-3 h-3 text-primary" />
              <span>{event.location}</span>
            </div>
          )}
        </div>

        {event.description && (
          <div className="pt-2 border-t border-border mt-2">
            <p className="text-[11px] text-muted-foreground leading-relaxed italic">
              {event.description}
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

