/**
 * DAY VIEW COMPONENT
 * Shows a single day with hourly time slots
 */
interface DayViewProps {
  selectedDate: Date;
  events: CalendarEvent[];
  users: User[];
  onEventClick: (event: CalendarEvent) => void;
}

const DayView: React.FC<DayViewProps> = ({ selectedDate, events, users, onEventClick }) => {
  const { settings, preferences } = useWorkspace();
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const startHour = settings.business_hours?.start ?? 0;
  const endHour = settings.business_hours?.end ?? 23;
  const timeSlots = useMemo(() => generateTimeSlots(startHour, endHour), [startHour, endHour]);
  const HOUR_HEIGHT = preferences.calendar_density === 'compact' ? 40 : 60;
  const locale = settings.language === 'sv' ? 'sv-SE' : 'en-US';

  useEffect(() => {
    if (scrollContainerRef.current && isToday(selectedDate)) {
      const now = new Date();
      if (now.getHours() >= startHour && now.getHours() <= endHour) {
        const scrollPosition = (now.getHours() - startHour - 1) * HOUR_HEIGHT;
        scrollContainerRef.current.scrollTop = Math.max(0, scrollPosition);
      }
    }
  }, [selectedDate, startHour, endHour, HOUR_HEIGHT]);

  const dayEvents = useMemo(() => {
    const dayStart = new Date(selectedDate);
    dayStart.setHours(0, 0, 0, 0);
    const dayEnd = new Date(selectedDate);
    dayEnd.setHours(23, 59, 59, 999);

    return events.filter(event => {
      const eventStart = new Date(event.startTime);
      const eventEnd = new Date(event.endTime);
      return eventStart <= dayEnd && eventEnd >= dayStart;
    });
  }, [events, selectedDate]);

  return (
    <div ref={scrollContainerRef} className="flex-1 overflow-y-auto scrollbar-dark">
      <div className="flex min-h-full">
        {/* Time column */}
        <div className="w-16 flex-shrink-0 border-r border-border bg-sidebar">
          <div className="h-4 border-b border-border" />
          <div className="h-4 border-b border-border" />
          {timeSlots.map((slot, index) => (
            <div key={index} style={{ height: `${HOUR_HEIGHT}px` }} className="border-b border-border relative">
              <span className="absolute -top-2 right-2 text-[10px] text-muted-foreground">
                {slot.label}
              </span>
            </div>
          ))}
        </div>

        {/* Day column with events */}
        <div className="flex-1 relative">
          <div className="h-4 border-b border-border" />

          {/* Current time indicator */}
          {isToday(selectedDate) && (
            <div
              className="absolute left-0 right-0 z-20 pointer-events-none"
              style={{
                top: `calc(1rem + ${(new Date().getHours() - startHour + new Date().getMinutes() / 60) * HOUR_HEIGHT}px)`,
              }}
            >
              <div className="flex items-center">
                <div className="w-2 h-2 bg-red-500 rounded-full -ml-1" />
                <div className="flex-1 h-px bg-red-500" />
              </div>
            </div>
          )}

          {/* Hour grid lines */}
          {timeSlots.map((_, index) => (
            <div key={index} style={{ height: `${HOUR_HEIGHT}px` }} className="border-b border-border" />
          ))}

          {/* Events */}
          <div className="absolute inset-x-0 bottom-0 top-4">
            {dayEvents.map((event) => (
              <EventCard
                key={event.id}
                event={event}
                onClick={() => onEventClick(event)}
                hourHeight={HOUR_HEIGHT}
                startHour={startHour}
                locale={locale}
                tooltipPosition="top"
                currentDate={selectedDate}
                users={users}
              />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

/**
 * WEEK VIEW COMPONENT
 * Shows 7 days with hourly time slots
 */
interface WeekViewProps {
  selectedDate: Date;
  selectedEndDate?: Date | null;
  events: CalendarEvent[];
  users: User[];
  onEventClick: (event: CalendarEvent) => void;
}

const WeekView: React.FC<WeekViewProps> = ({ selectedDate, selectedEndDate, events, users, onEventClick }) => {
  const { settings, preferences } = useWorkspace();
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const startHour = settings.business_hours?.start ?? 0;
  const endHour = settings.business_hours?.end ?? 23;
  const timeSlots = useMemo(() => generateTimeSlots(startHour, endHour), [startHour, endHour]);
  const HOUR_HEIGHT = preferences.calendar_density === 'compact' ? 40 : 60;
  const locale = settings.language === 'sv' ? 'sv-SE' : 'en-US';

  const weekDays = useMemo(() => {
    if (selectedEndDate) {
      const days = [];
      const current = new Date(selectedDate);
      while (current <= selectedEndDate) {
        days.push({
          date: new Date(current),
          name: current.toLocaleDateString(locale, { weekday: 'short' }),
          dayOfMonth: current.getDate(),
          isToday: isToday(current),
          isWeekend: current.getDay() === 0 || current.getDay() === 6
        });
        current.setDate(current.getDate() + 1);
      }
      return days;
    }
    const weekStart = getStartOfWeek(selectedDate, settings.week_start);
    return generateWeekDays(weekStart, locale);
  }, [selectedDate, selectedEndDate, settings.week_start, locale]);

  useEffect(() => {
    if (scrollContainerRef.current) {
      const now = new Date();
      if (now.getHours() >= startHour && now.getHours() <= endHour) {
        const scrollPosition = (now.getHours() - startHour - 1) * HOUR_HEIGHT;
        scrollContainerRef.current.scrollTop = Math.max(0, scrollPosition);
      }
    }
  }, [startHour, endHour, HOUR_HEIGHT]);

  const getEventsForDay = (date: Date) => {
    const dayStart = new Date(date);
    dayStart.setHours(0, 0, 0, 0);
    const dayEnd = new Date(date);
    dayEnd.setHours(23, 59, 59, 999);

    return events.filter(event => {
      const eventStart = new Date(event.startTime);
      const eventEnd = new Date(event.endTime);
      return eventStart <= dayEnd && eventEnd >= dayStart;
    });
  };

  return (
    <div ref={scrollContainerRef} className="flex-1 overflow-y-auto scrollbar-dark">
      <div className="flex min-h-full">
        {/* Time column */}
        <div className="w-16 flex-shrink-0 border-r border-border bg-sidebar">
          <div className="h-4 border-b border-border" />
          {timeSlots.map((slot, index) => (
            <div key={index} style={{ height: `${HOUR_HEIGHT}px` }} className="border-b border-border relative">
              <span className="absolute -top-2 right-2 text-[10px] text-muted-foreground">
                {slot.label}
              </span>
            </div>
          ))}
        </div>

        {/* Day columns with events */}
        <div className="flex-1 grid relative divide-x divide-border" style={{ gridTemplateColumns: `repeat(${weekDays.length}, minmax(0, 1fr))` }}>
          {/* Current time indicator */}
          {weekDays.some(day => day.isToday) && (
            <div
              className="absolute left-0 right-0 z-20 pointer-events-none"
              style={{
                top: `calc(1rem + ${(new Date().getHours() - startHour + new Date().getMinutes() / 60) * HOUR_HEIGHT}px)`,
              }}
            >
              <div className="flex items-center">
                <div className="w-2 h-2 bg-red-500 rounded-full -ml-1" />
                <div className="flex-1 h-px bg-red-500" />
              </div>
            </div>
          )}

          {/* Grid lines and events for each day */}
          {weekDays.map((day, dayIndex) => (
            <div
              key={dayIndex}
              className={cn(
                'relative border-r border-border last:border-r-0',
                day.isWeekend && 'bg-muted/50 dark:bg-[#0F1115]'
              )}
            >
              <div className="h-4 border-b border-border" />

              {/* Hour grid lines */}
              {timeSlots.map((_, hourIndex) => (
                <div key={hourIndex} style={{ height: `${HOUR_HEIGHT}px` }} className="border-b border-border" />
              ))}

              {/* Events for this day */}
              <div className="absolute inset-x-0 bottom-0 top-4">
                {getEventsForDay(day.date).map((event) => (
                  <EventCard
                    key={event.id}
                    event={event}
                    onClick={() => onEventClick(event)}
                    hourHeight={HOUR_HEIGHT}
                    startHour={startHour}
                    locale={locale}
                    tooltipPosition="side"
                    currentDate={day.date}
                    users={users}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

/**
 * MONTH VIEW COMPONENT
 * Shows a full month in a grid layout
 */
interface MonthViewProps {
  selectedDate: Date;
  events: CalendarEvent[];
  users: User[];
  onEventClick: (event: CalendarEvent) => void;
  onDateChange: (date: Date) => void;
}

const MonthView: React.FC<MonthViewProps> = ({ selectedDate, events, onEventClick, onDateChange }) => {
  const { settings } = useWorkspace();
  const locale = settings.language === 'sv' ? 'sv-SE' : 'en-US';

  const calendarDays = useMemo(() => {
    const year = selectedDate.getFullYear();
    const month = selectedDate.getMonth();

    const firstDayOfMonth = new Date(year, month, 1);
    const lastDayOfMonth = new Date(year, month + 1, 0);

    const startDayOfWeek = firstDayOfMonth.getDay();
    const diffToStart = (startDayOfWeek < settings.week_start ? 7 : 0) + startDayOfWeek - settings.week_start;

    const daysInMonth = lastDayOfMonth.getDate();
    const daysInPrevMonth = new Date(year, month, 0).getDate();

    const days: Array<{
      date: Date;
      dayOfMonth: number;
      isCurrentMonth: boolean;
      isToday: boolean;
      events: CalendarEvent[];
    }> = [];

    for (let i = diffToStart - 1; i >= 0; i--) {
      const date = new Date(year, month - 1, daysInPrevMonth - i);
      days.push({
        date,
        dayOfMonth: daysInPrevMonth - i,
        isCurrentMonth: false,
        isToday: isToday(date),
        events: events.filter(e => isSameDay(e.startTime, date)),
      });
    }

    for (let day = 1; day <= daysInMonth; day++) {
      const date = new Date(year, month, day);
      days.push({
        date,
        dayOfMonth: day,
        isCurrentMonth: true,
        isToday: isToday(date),
        events: events.filter(e => isSameDay(e.startTime, date)),
      });
    }

    const remainingCells = 42 - days.length;
    for (let day = 1; day <= remainingCells; day++) {
      const date = new Date(year, month + 1, day);
      days.push({
        date,
        dayOfMonth: day,
        isCurrentMonth: false,
        isToday: isToday(date),
        events: events.filter(e => isSameDay(e.startTime, date)),
      });
    }

    return days;
  }, [selectedDate, events, settings.week_start]);

  const dayLabels = settings.week_start === 1
    ? ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
    : ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

  return (
    <div className="flex-1 overflow-y-auto scrollbar-dark p-4">
      {/* Day labels */}
      <div className="grid grid-cols-7 gap-1 mb-2">
        {dayLabels.map((label, index) => (
          <div key={index} className="text-center text-xs text-muted-foreground font-medium py-2">
            {label}
          </div>
        ))}
      </div>

      {/* Calendar grid */}
      <div className="grid grid-cols-7 gap-1">
        {calendarDays.map((day, index) => (
          <div
            key={index}
            onClick={() => onDateChange(day.date)}
            className={cn(
              'min-h-[100px] p-2 rounded-lg border cursor-pointer transition-all duration-150',
              'hover:border-primary/50',
              day.isCurrentMonth
                ? 'bg-muted border-border'
                : 'bg-background border-border',
              isSameDay(day.date, selectedDate) && 'ring-2 ring-primary'
            )}
          >
            {/* Day number */}
            <div className={cn(
              'text-sm font-medium mb-1',
              day.isToday
                ? 'w-7 h-7 flex items-center justify-center bg-primary text-white rounded-full'
                : day.isCurrentMonth ? 'text-foreground' : 'text-muted-foreground'
            )}>
              {day.dayOfMonth}
            </div>

            {/* Events for this day */}
            <div className="space-y-1">
              {day.events.slice(0, 3).map((event) => (
                <MonthEventCard
                  key={event.id}
                  event={event}
                  onClick={(e) => {
                    e.stopPropagation();
                    onEventClick(event);
                  }}
                  locale={locale}
                />
              ))}
              {day.events.length > 3 && (
                <div className="text-[10px] text-muted-foreground pl-1">
                  +{day.events.length - 3} more
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

/**
 * AGENDA VIEW COMPONENT
 * Shows events in a chronological list
 */
interface AgendaViewProps {
  events: CalendarEvent[];
  users: User[];
  onEventClick: (event: CalendarEvent) => void;
}

const AgendaView: React.FC<AgendaViewProps> = ({ events, onEventClick }) => {
  const { settings } = useWorkspace();
  const { t } = useTranslation();
  const locale = settings.language === 'sv' ? 'sv-SE' : 'en-US';

  const groupedEvents = useMemo(() => {
    const sortedEvents = [...events].sort((a, b) =>
      a.startTime.getTime() - b.startTime.getTime()
    );

    const groups: Array<{
      date: Date;
      dateLabel: string;
      isToday: boolean;
      events: CalendarEvent[];
    }> = [];

    sortedEvents.forEach((event) => {
      const existingGroup = groups.find(g => isSameDay(g.date, event.startTime));
      if (existingGroup) {
        existingGroup.events.push(event);
      } else {
        const isEventToday = isToday(event.startTime);
        groups.push({
          date: event.startTime,
          dateLabel: isEventToday
            ? t('common.today')
            : event.startTime.toLocaleDateString(locale, {
              weekday: 'long',
              month: 'long',
              day: 'numeric'
            }),
          isToday: isEventToday,
          events: [event],
        });
      }
    });

    return groups;
  }, [events, locale, t]);

  return (
    <div className="flex-1 overflow-y-auto scrollbar-dark p-4">
      {groupedEvents.length === 0 ? (
        <div className="flex flex-col items-center justify-center h-full text-muted-foreground">
          <CalendarIcon className="w-12 h-12 mb-4 opacity-50" />
          <p className="text-lg">No upcoming events</p>
          <p className="text-sm">Your scheduled events will appear here</p>
        </div>
      ) : (
        <div className="max-w-3xl mx-auto space-y-6">
          {groupedEvents.map((group, groupIndex) => (
            <div key={groupIndex}>
              {/* Date header */}
              <div className="flex items-center gap-3 mb-3">
                <div className={cn(
                  'w-10 h-10 rounded-lg flex flex-col items-center justify-center text-xs',
                  group.isToday
                    ? 'bg-primary text-white'
                    : 'bg-muted text-muted-foreground'
                )}>
                  <span className="text-[10px] uppercase">
                    {group.date.toLocaleDateString('en-US', { month: 'short' })}
                  </span>
                  <span className="font-bold">{group.date.getDate()}</span>
                </div>
                <h3 className={cn(
                  'text-lg font-medium',
                  group.isToday ? 'text-foreground' : 'text-muted-foreground'
                )}>
                  {group.dateLabel}
                </h3>
              </div>

              {/* Events for this date */}
              <div className="space-y-2 ml-12">
                {group.events.map((event) => {
                  const categoryConfig = getCategoryConfig(event.category);
                  return (
                    <div
                      key={event.id}
                      onClick={() => onEventClick(event)}
                      className="flex items-center gap-4 p-3 rounded-lg bg-muted 
                                 border border-border hover:border-primary/50
                                 cursor-pointer transition-all duration-150"
                    >
                      {/* Time */}
                      <div className="flex-shrink-0 w-20 text-right">
                        <div className="text-foreground text-sm font-medium">
                          {event.startTime.toLocaleTimeString(locale, {
                            hour: '2-digit',
                            minute: '2-digit',
                            hour12: false
                          })}
                        </div>
                        <div className="text-muted-foreground text-xs">
                          {event.endTime.toLocaleTimeString(locale, {
                            hour: '2-digit',
                            minute: '2-digit',
                            hour12: false
                          })}
                        </div>
                      </div>

                      {/* Category indicator */}
                      <div
                        className="w-1 h-10 rounded-full flex-shrink-0"
                        style={{ backgroundColor: categoryConfig.color }}
                      />

                      {/* Event details */}
                      <div className="flex-1 min-w-0">
                        <div className="text-foreground font-medium truncate">
                          {event.title}
                        </div>
                        {event.description && (
                          <div className="text-muted-foreground text-sm truncate">
                            {event.description}
                          </div>
                        )}
                      </div>

                      {/* Location */}
                      {event.location && (
                        <div className="flex items-center gap-1 text-muted-foreground text-sm flex-shrink-0">
                          <MapPin className="w-4 h-4" />
                          <span>{event.location}</span>
                        </div>
                      )}

                      {/* Category badge */}
                      <span
                        className="px-2 py-1 rounded text-xs flex-shrink-0"
                        style={{
                          backgroundColor: categoryConfig.bgColor,
                          color: categoryConfig.color
                        }}
                      >
                        {categoryConfig.label}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

/**
 * Main CalendarView Component
 * Renders the appropriate view based on the current view mode
 */
interface CalendarViewProps {
  selectedDate: Date;
  selectedEndDate?: Date | null;
  view: ViewType;
  events: CalendarEvent[];
  users: User[];
  onDateChange: (date: Date) => void;
  onViewChange: (view: ViewType) => void;
  onEventClick: (event: CalendarEvent) => void;
  onNext: () => void;
  onPrevious: () => void;
  onToday: () => void;
}

export const CalendarView: React.FC<CalendarViewProps> = ({
  selectedDate,
  selectedEndDate,
  view,
  events,
  users,
  onDateChange,
  onViewChange,
  onEventClick,
  onNext,
  onPrevious,
  onToday,
}) => {
  const { settings } = useWorkspace();
  const { t } = useTranslation();
  const locale = settings.language === 'sv' ? 'sv-SE' : 'en-US';

  const weekDays = useMemo(() => {
    if (selectedEndDate && view === 'week') {
      const days = [];
      const current = new Date(selectedDate);
      while (current <= selectedEndDate) {
        days.push({
          date: new Date(current),
          name: current.toLocaleDateString(locale, { weekday: 'short' }),
          dayOfMonth: current.getDate(),
          isToday: isToday(current),
          isWeekend: current.getDay() === 0 || current.getDay() === 6
        });
        current.setDate(current.getDate() + 1);
      }
      return days;
    }
    const weekStart = getStartOfWeek(selectedDate, settings.week_start);
    return generateWeekDays(weekStart, locale);
  }, [selectedDate, selectedEndDate, view, settings.week_start, locale]);

  /**
   * Format the date range for the header based on current view
   */
  const formatDateRange = () => {
    switch (view) {
      case 'day':
        return selectedDate.toLocaleDateString(locale, {
          weekday: 'long',
          month: 'long',
          day: 'numeric',
          year: 'numeric'
        });

      case 'week': {
        const start = weekDays[0].date;
        const end = weekDays[weekDays.length - 1].date;
        if (start.getMonth() === end.getMonth()) {
          return `${start.toLocaleDateString(locale, { month: 'long' })} ${start.getDate()} - ${end.getDate()}, ${start.getFullYear()}`;
        } else if (start.getFullYear() === end.getFullYear()) {
          return `${start.toLocaleDateString(locale, { month: 'short', day: 'numeric' })} - ${end.toLocaleDateString(locale, { month: 'short', day: 'numeric' })}, ${start.getFullYear()}`;
        } else {
          return `${start.toLocaleDateString(locale, { month: 'short', day: 'numeric', year: 'numeric' })} - ${end.toLocaleDateString(locale, { month: 'short', day: 'numeric', year: 'numeric' })}`;
        }
      }

      case 'month':
        return formatMonthYear(selectedDate, locale);

      case 'agenda':
        return t('scheduler.upcoming_events');

      default:
        return '';
    }
  };

  /**
   * Render the appropriate view based on current view mode
   */
  const renderView = () => {
    switch (view) {
      case 'day':
        return (
          <DayView
            selectedDate={selectedDate}
            events={events}
            users={users}
            onEventClick={onEventClick}
          />
        );

      case 'week':
        return (
          <WeekView
            selectedDate={selectedDate}
            selectedEndDate={selectedEndDate}
            events={events}
            users={users}
            onEventClick={onEventClick}
          />
        );

      case 'month':
        return (
          <MonthView
            selectedDate={selectedDate}
            events={events}
            users={users}
            onEventClick={onEventClick}
            onDateChange={onDateChange}
          />
        );

      case 'agenda':
        return (
          <AgendaView
            events={events}
            users={users}
            onEventClick={onEventClick}
          />
        );

      default:
        return null;
    }
  };

  /**
   * Render the appropriate header based on view mode
   */
  const renderHeader = () => {
    if (view === 'month') {
      return null;
    }

    if (view === 'agenda') {
      return null;
    }

    if (view === 'day') {
      // Day view shows single day header
      return (
        <div className="flex border-b border-border overflow-y-scroll scrollbar-dark" style={{ scrollbarColor: 'transparent transparent' }}>
          <div className="w-16 flex-shrink-0 border-r border-border" />
          <div className="flex-1 px-2 py-3 text-center">
            <div className={cn(
              'text-xs uppercase tracking-wider',
              isToday(selectedDate) ? 'text-primary' : 'text-muted-foreground'
            )}>
              {selectedDate.toLocaleDateString(locale, { weekday: 'long' })}
            </div>
            <div className={cn(
              'text-lg font-semibold mt-1',
              isToday(selectedDate)
                ? 'w-8 h-8 mx-auto flex items-center justify-center bg-primary text-white rounded-full'
                : 'text-foreground'
            )}>
              {selectedDate.getDate()}
            </div>
          </div>
        </div>
      );
    }

    // Week view - show dynamic days
    return (
      <div className="flex border-b border-border overflow-y-scroll scrollbar-dark" style={{ scrollbarColor: 'transparent transparent' }}>
        <div className="w-16 flex-shrink-0 border-r border-border bg-sidebar">
          <div className="h-4 border-b border-border" />
        </div>
        <div className="flex-1 grid divide-x divide-border" style={{ gridTemplateColumns: `repeat(${weekDays.length}, minmax(0, 1fr))` }}>
          {weekDays.map((day, index) => (
            <div
              key={index}
              className={cn(
                'px-2 py-3 text-center border-r border-border last:border-r-0',
                day.isWeekend && 'bg-muted/50 dark:bg-[#0F1115]'
              )}
            >
              <div className={cn(
                'text-xs uppercase tracking-wider',
                day.isToday ? 'text-primary' : 'text-muted-foreground'
              )}>
                {day.name}
              </div>
              <div className={cn(
                'text-lg font-semibold mt-1',
                day.isToday
                  ? 'w-8 h-8 mx-auto flex items-center justify-center bg-primary text-white rounded-full'
                  : 'text-foreground'
              )}>
                {day.dayOfMonth}
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-background">
      {/* Header Toolbar */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-border">
        {/* Left side - Navigation and date display */}
        <div className="flex items-center gap-4">
          {/* Navigation buttons */}
          <div className="flex items-center gap-1">
            <button
              onClick={onPrevious}
              className="p-2 hover:bg-muted rounded-md transition-colors"
            >
              <ChevronLeft className="w-5 h-5 text-muted-foreground" />
            </button>
            <button
              onClick={onToday}
              className="px-3 py-1.5 text-sm text-foreground hover:bg-muted rounded-md transition-colors"
            >
              Today
            </button>
            <button
              onClick={onNext}
              className="p-2 hover:bg-muted rounded-md transition-colors"
            >
              <ChevronRight className="w-5 h-5 text-muted-foreground" />
            </button>
          </div>

          {/* Date display */}
          <div className="flex items-center gap-2">
            <CalendarIcon className="w-5 h-5 text-muted-foreground" />
            <span className="text-foreground font-medium">
              {formatDateRange()}
            </span>
          </div>
        </div>

        {/* Right side - View mode selector */}
        <div className="flex items-center bg-secondary rounded-lg p-1">
          {VIEW_MODES.map((mode) => (
            <button
              key={mode.id}
              onClick={() => onViewChange(mode.id)}
              className={cn(
                'px-3 py-1.5 text-sm rounded-md transition-all duration-150',
                view === mode.id
                  ? 'bg-primary/80 text-white'
                  : 'text-muted-foreground hover:text-foreground hover:bg-muted'
              )}
            >
              {mode.label}
            </button>
          ))}
        </div>
      </div>

      {/* View-specific header (day/week column headers) */}
      {renderHeader()}

      {/* Main content - renders the active view */}
      {renderView()}
    </div>
  );
};

export default CalendarView;

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '@/hooks/useAuth';
import { supabase } from '@/lib/supabase';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Switch } from '@/components/ui/switch';
import { Mail, BellRing, Check } from 'lucide-react';
import { cn } from '@/lib/utils';

interface NotificationsSettingsProps {
  setIsSaving: (val: boolean) => void;
}

export const NotificationsSettings: React.FC<NotificationsSettingsProps> = ({ setIsSaving }) => {
  const { t } = useTranslation();
  const { user } = useAuth();
  const [notifSettings, setNotifSettings] = useState({
    on: true,
    type: 'full_content'
  });

  useEffect(() => {
    async function loadUserSettings() {
      if (!user) return;
      const { data } = await supabase.from('users').select('notifications_on, notification_type').eq('id', user.id).single();
      if (data) {
        setNotifSettings({
          on: !!data.notifications_on,
          type: data.notification_type || 'full_content'
        });
      }
    }
    loadUserSettings();
  }, [user]);

  const updateNotifSetting = async (key: 'on' | 'type', value: any) => {
    if (!user) return;
    setIsSaving(true);
    const newSettings = { ...notifSettings, [key]: value };
    setNotifSettings(newSettings);

    await supabase.from('users').update({
      notifications_on: newSettings.on,
      notification_type: newSettings.type
    }).eq('id', user.id);

    setTimeout(() => setIsSaving(false), 500);
  };

  return (
    <Card className="bg-card/40 backdrop-blur-sm border-2 border-border/50 shadow-sm overflow-hidden">
      <CardHeader className="pb-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-3 rounded-2xl bg-primary/10 text-primary">
              <Mail className="w-6 h-6" />
            </div>
            <div>
              <CardTitle className="text-xl">{t('settings.notifications.title')}</CardTitle>
              <CardDescription className="mt-1">
                {t('settings.notifications.desc')}
              </CardDescription>
            </div>
          </div>
          <Switch
            checked={notifSettings.on}
            onCheckedChange={(c) => updateNotifSetting('on', c)}
            className="data-[state=checked]:bg-primary"
          />
        </div>
      </CardHeader>
      <CardContent className="space-y-8">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <button
            disabled={!notifSettings.on}
            onClick={() => updateNotifSetting('type', 'full_content')}
            className={cn(
              "flex items-start gap-4 p-5 rounded-2xl border-2 transition-all text-left group relative",
              notifSettings.type === 'full_content'
                ? "border-primary bg-primary/10"
                : "border-border/50 bg-background/50 hover:border-primary/30",
              !notifSettings.on && "opacity-50 cursor-not-allowed"
            )}
          >
            <div className={cn(
              "mt-1 p-2.5 rounded-xl transition-colors shadow-sm",
              notifSettings.type === 'full_content' ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground"
            )}>
              <BellRing className="w-5 h-5" />
            </div>
            <div>
              <div className={cn("font-bold", notifSettings.type === 'full_content' ? "text-foreground" : "text-muted-foreground")}>{t('settings.notifications.full_content')}</div>
              <div className="text-xs text-muted-foreground mt-1.5 leading-relaxed">{t('settings.notifications.full_content_desc')}</div>
            </div>
            {notifSettings.type === 'full_content' && (
              <div className="absolute top-3 right-3">
                <Check className="w-4 h-4 text-primary" />
              </div>
            )}
          </button>

          <button
            disabled={!notifSettings.on}
            onClick={() => updateNotifSetting('type', 'alert_only')}
            className={cn(
              "flex items-start gap-4 p-5 rounded-2xl border-2 transition-all text-left group relative",
              notifSettings.type === 'alert_only'
                ? "border-primary bg-primary/10"
                : "border-border/50 bg-background/50 hover:border-primary/30",
              !notifSettings.on && "opacity-50 cursor-not-allowed"
            )}
          >
            <div className={cn(
              "mt-1 p-2.5 rounded-xl transition-colors shadow-sm",
              notifSettings.type === 'alert_only' ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground"
            )}>
              <Mail className="w-5 h-5" />
            </div>
            <div>
              <div className={cn("font-bold", notifSettings.type === 'alert_only' ? "text-foreground" : "text-muted-foreground")}>{t('settings.notifications.alert_only')}</div>
              <div className="text-xs text-muted-foreground mt-1.5 leading-relaxed">{t('settings.notifications.alert_only_desc')}</div>
            </div>
            {notifSettings.type === 'alert_only' && (
              <div className="absolute top-3 right-3">
                <Check className="w-4 h-4 text-primary" />
              </div>
            )}
          </button>
        </div>

        <div className="bg-muted/30 p-4 rounded-xl border border-border/50 flex items-center gap-3">
          <div className="w-2 h-2 rounded-full bg-primary animate-pulse" />
          <p className="text-xs text-muted-foreground font-medium">{t('settings.notifications.no_spam')}</p>
        </div>
      </CardContent>
    </Card>
  );
};

import React from 'react';
import { useTranslation } from 'react-i18next';
import { useWorkspace } from '@/contexts/WorkspaceContext';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Slider } from '@/components/ui/slider';
import { Calendar, Clock, Layout, Maximize2 } from 'lucide-react';
import { cn } from '@/lib/utils';

interface SchedulerSettingsProps {
  setIsSaving: (val: boolean) => void;
}

export const SchedulerSettings: React.FC<SchedulerSettingsProps> = ({ setIsSaving }) => {
  const { t } = useTranslation();
  const { settings, updateSettings, preferences, updatePreferences } = useWorkspace();

  // Local state for smooth slider experience
  const [localHours, setLocalHours] = React.useState({
    start: settings.business_hours?.start || 7,
    end: settings.business_hours?.end || 17
  });

  // Sync local state when settings change from elsewhere
  React.useEffect(() => {
    setLocalHours({
      start: settings.business_hours?.start || 7,
      end: settings.business_hours?.end || 17
    });
  }, [settings.business_hours]);

  const handleUpdateSettings = async (newSettings: any) => {
    setIsSaving(true);
    await updateSettings(newSettings);
    setTimeout(() => setIsSaving(false), 500);
  };

  const handleUpdatePreferences = async (newPrefs: any) => {
    setIsSaving(true);
    await updatePreferences(newPrefs);
    setTimeout(() => setIsSaving(false), 500);
  };

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Calendar Display */}
        <Card className="bg-card/40 backdrop-blur-sm border-2 border-border/50 shadow-sm">
          <CardHeader>
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-blue-500/10 text-blue-500">
                <Layout className="w-5 h-5" />
              </div>
              <div>
                <CardTitle className="text-lg">{t('settings.scheduler.display')}</CardTitle>
                <CardDescription>{t('settings.scheduler.display_desc')}</CardDescription>
              </div>
            </div>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="space-y-2">
              <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">{t('settings.scheduler.default_view')}</Label>
              <Select
                value={settings.default_calendar_view || 'week'}
                onValueChange={(val) => handleUpdateSettings({ default_calendar_view: val })}
              >
                <SelectTrigger className="bg-background/50 border-border/50 h-10">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="day">{t('scheduler.views.day')}</SelectItem>
                  <SelectItem value="week">{t('scheduler.views.week')}</SelectItem>
                  <SelectItem value="month">{t('scheduler.views.month')}</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-3">
              <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">{t('settings.scheduler.density')}</Label>
              <div className="grid grid-cols-2 gap-3">
                <button
                  onClick={() => handleUpdatePreferences({ calendar_density: 'compact' })}
                  className={cn(
                    "flex flex-col items-center justify-center p-3 rounded-xl border-2 transition-all",
                    preferences.calendar_density === 'compact' ? "border-primary bg-primary/10 text-primary shadow-sm" : "border-border/40 bg-background/40 hover:border-primary/40"
                  )}
                >
                  <Maximize2 className="w-4 h-4 mb-2 rotate-45 scale-75" />
                  <span className="text-xs font-medium">{t('settings.scheduler.density_compact')}</span>
                </button>
                <button
                  onClick={() => handleUpdatePreferences({ calendar_density: 'relaxed' })}
                  className={cn(
                    "flex flex-col items-center justify-center p-3 rounded-xl border-2 transition-all",
                    preferences.calendar_density === 'relaxed' ? "border-primary bg-primary/10 text-primary shadow-sm" : "border-border/40 bg-background/40 hover:border-primary/40"
                  )}
                >
                  <Maximize2 className="w-4 h-4 mb-2" />
                  <span className="text-xs font-medium">{t('settings.scheduler.density_relaxed')}</span>
                </button>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Working Hours */}
        <Card className="bg-card/40 backdrop-blur-sm border-2 border-border/50 shadow-sm">
          <CardHeader>
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-orange-500/10 text-orange-500">
                <Clock className="w-5 h-5" />
              </div>
              <div>
                <CardTitle className="text-lg">{t('settings.scheduler.hours')}</CardTitle>
                <CardDescription>{t('settings.scheduler.hours_desc')}</CardDescription>
              </div>
            </div>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="space-y-4">
              <div className="space-y-2">
                <div className="flex justify-between">
                  <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">{t('settings.scheduler.start_hour')}</Label>
                  <span className="text-xs font-mono">{localHours.start}:00</span>
                </div>
                <Slider
                  value={[localHours.start]}
                  min={0}
                  max={12}
                  step={1}
                  onValueChange={([val]) => setLocalHours(prev => ({ ...prev, start: val }))}
                  onValueCommit={([val]) => handleUpdateSettings({ 
                    business_hours: { ...settings.business_hours, start: val } 
                  })}
                />
              </div>

              <div className="space-y-2">
                <div className="flex justify-between">
                  <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">{t('settings.scheduler.end_hour')}</Label>
                  <span className="text-xs font-mono">{localHours.end}:00</span>
                </div>
                <Slider
                  value={[localHours.end]}
                  min={13}
                  max={23}
                  step={1}
                  onValueChange={([val]) => setLocalHours(prev => ({ ...prev, end: val }))}
                  onValueCommit={([val]) => handleUpdateSettings({ 
                    business_hours: { ...settings.business_hours, end: val } 
                  })}
                />
              </div>
            </div>
            <p className="text-[10px] text-muted-foreground italic">
              {t('settings.scheduler.hours_info')}
