import { useState, useEffect, useCallback } from 'react';
import { toast } from "sonner";
import { supabase } from '@/lib/supabase';
import { useWorkspace } from '@/contexts/WorkspaceContext';
import { useAuth } from '@/hooks/useAuth';
import type { TimeReportUI, DevRole, NavLevel } from '../types';
import type { User } from '@/types';

interface WorkspaceRow {
  id: string;
  name: string;
}

interface TeamRow {
  id: string;
  name: string;
  workspace_id: string;
}

export const useTimeManager = () => {
  const { workspaceId } = useWorkspace();
  const { user } = useAuth();

  const activeRole: DevRole = user?.role as DevRole || 'admin';
  const [shifts, setShifts] = useState<TimeReportUI[]>([]);
  const [dbTeams, setDbTeams] = useState<TeamRow[]>([]);
  const [dbWorkspaces, setDbWorkspaces] = useState<WorkspaceRow[]>([]);
  const [dbUsers, setDbUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentLevel, setCurrentLevel] = useState<NavLevel>('team_overview');
  const [selectedContext, setSelectedContext] = useState<{ type: 'employee' | 'team' | null, id: string | null }>({ type: null, id: null });

  const [filterType, setFilterType] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedShifts, setSelectedShifts] = useState<string[]>([]);
  const [listMode, setListMode] = useState<'current' | 'history'>('current');
  const [isDeleteAlertOpen, setIsDeleteAlertOpen] = useState(false);
  const [hasApprovePermission, setHasApprovePermission] = useState(false);

  const fetchData = useCallback(async () => {
    if (!workspaceId && activeRole !== 'platform_admin') return;

    setLoading(true);
    try {
      let reportsData: any[] = [];
      let teamsData: TeamRow[] = [];
      let workspacesData: WorkspaceRow[] = [];
      let usersData: User[] = [];

      const promises = [];

      if (activeRole === 'platform_admin') {
        promises.push(supabase.from('workspaces').select('*').then(({ data }) => workspacesData = data || []));
        promises.push(supabase.from('teams').select('*').then(({ data }) => teamsData = data || []));
        promises.push(supabase.from('users').select('*').then(({ data }) => usersData = data || []));
      } else {
        promises.push(supabase.from('teams').select('*').eq('workspace_id', workspaceId).then(({ data }) => teamsData = data || []));
        promises.push(supabase.from('users').select('*').eq('workspace_id', workspaceId).then(({ data }) => usersData = data || []));
      }

      await Promise.all(promises);
      setDbWorkspaces(workspacesData);
      setDbTeams(teamsData);
      setDbUsers(usersData);

      let query = supabase.from('time_reports').select('*, user:users(*)');

      if (activeRole === 'admin') {
        query = query.eq('workspace_id', workspaceId);
      } else if (activeRole === 'assistant') {
        query = query.eq('user_id', user?.id);
      }

      const { data: r, error } = await query;
      if (error) throw error;
      reportsData = r || [];

      const mapped: TimeReportUI[] = reportsData.map(dbShift => {
        const team = teamsData.find(t => t.id === dbShift.team_id);
        const teamName = team?.name || 'Odelat team';
        const uData = Array.isArray(dbShift.user) ? dbShift.user[0] : dbShift.user;
        const employeeName = uData ? (uData.full_name || uData.email || 'Ok├ñnd Agent') : 'Ok├ñnd Agent';

        return {
          id: dbShift.id,
          employeeId: dbShift.user_id,
          employee: employeeName,
          role: uData?.role === 'admin' ? 'Administrat├╢r' : 'Assistent',
          teamId: dbShift.team_id,
          team: teamName,
          workspaceId: dbShift.workspace_id,
          date: new Date(dbShift.date).toLocaleDateString('sv-SE'),
          start: dbShift.start_time || '08:00',
          end: dbShift.end_time || '17:00',
          duration: dbShift.hours || 0,
          break: 0,
          status: dbShift.status,
          location: '',
          note: dbShift.note || ''
        };
      });
      setShifts(mapped);
    } catch (error: unknown) {
      console.error('Error fetching data:', error);
      const message = error instanceof Error ? error.message : 'Ok├ñnt fel';
      toast.error('Kunde inte h├ñmta data: ' + message);
    } finally {
      setLoading(false);
    }
  }, [workspaceId, activeRole, user?.id]);

  useEffect(() => {
    fetchData().catch(console.error);

    const channel = supabase.channel('timemanager-reports')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'time_reports' }, () => { fetchData(); })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'teams' }, () => { fetchData(); })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'workspaces' }, () => { fetchData(); })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [fetchData]);

  useEffect(() => {
    if (activeRole === 'platform_admin') {
      setCurrentLevel('platform_overview');
    } else {
      setCurrentLevel('team_overview');
    }
    setSelectedContext({ type: null, id: null });
  }, [activeRole]);

  useEffect(() => {
    async function checkPerms() {
      if (!user) return;
      if (activeRole === 'admin' || activeRole === 'platform_admin') {
        setHasApprovePermission(true);
        return;
      }

      const { data: memberships } = await supabase.from('team_members').select('role_id').eq('user_id', user.id);
      if (memberships) {
        const roleIds = memberships.map(m => m.role_id).filter(Boolean);
        if (roleIds.length > 0) {
          const { data: roles } = await supabase.from('workspace_roles').select('permissions').in('id', roleIds);
          if (roles?.some(r => (r.permissions as Record<string, boolean>)?.can_approve_time_reports)) {
            setHasApprovePermission(true);
            return;
          }
        }
      }
      setHasApprovePermission(false);
    }
    checkPerms();
  }, [activeRole, user]);

  const openEmployeeShifts = (empId: string) => {
    setSelectedContext({ type: 'employee', id: empId });
    setCurrentLevel('shift_list');
    setFilterType('all');
    setSearchQuery('');
    setListMode('current');
  };

  const openTeamShifts = (teamName: string) => {
    setSelectedContext({ type: 'team', id: teamName });
    setCurrentLevel('shift_list');
    setFilterType('all');
    setSearchQuery('');
    setListMode('current');
  };

  const handleApprove = async () => {
    if (selectedShifts.length === 0) return;

    const { error } = await supabase.from('time_reports').update({ status: 'approved' }).in('id', selectedShifts);
    if (error) {
      toast.error("Kunde inte godk├ñnna rapporter: " + error.message);
      return;
    }

    toast.success(`${selectedShifts.length} rapporter har godk├ñnts`);
    setSelectedShifts([]);
    fetchData();
  };

  const handleDelete = async () => {
    if (selectedShifts.length === 0) return;

    const { error } = await supabase.from('time_reports').delete().in('id', selectedShifts);
    if (error) {
      toast.error("Kunde inte radera rapporter: " + error.message);
      return;
    }

    toast.success(`${selectedShifts.length} rapporter har raderats`);
    setSelectedShifts([]);
    setIsDeleteAlertOpen(false);
    fetchData();
  };

  return {
    workspaceId,
    activeRole,
    shifts,
    dbTeams,
    dbWorkspaces,
    dbUsers,
    loading,
    currentLevel,
    selectedContext,
    filterType,
    searchQuery,
    currentPage,
    selectedShifts,
    listMode,
    isDeleteAlertOpen,
    hasApprovePermission,
    setListMode,
    setFilterType,
    setSearchQuery,
    setCurrentPage,
    setSelectedShifts,
    setIsDeleteAlertOpen,
    openEmployeeShifts,
    openTeamShifts,
    handleApprove,
    handleDelete
  };
};

import { supabase } from '@/lib/supabase';
import type { CalendarEvent } from '@/types';

interface EventMetadata {
  category?: string;
  description?: string;
  location?: string;
  isAllDay?: boolean;
  attendees?: string[];
}

export const eventService = {
  /**
   * Fetch all events for a specific workspace
   */
  async getWorkspaceEvents(workspaceId: string): Promise<CalendarEvent[]> {
    const { data, error } = await supabase
      .from('events')
      .select('*')
      .eq('workspace_id', workspaceId);

    if (error) throw new Error(error.message);

    return (data || []).map((event) => {
      const metadata = (event.metadata as unknown as EventMetadata) || {};
      return {
        id: event.id,
        title: event.title,
        startTime: new Date(event.start_time),
        endTime: new Date(event.end_time),
        category: (metadata.category as any) || 'other',
        description: metadata.description || '',
        location: metadata.location || '',
        isAllDay: metadata.isAllDay || false,
        attendees: metadata.attendees || [],
        teamId: event.team_id,
        assigneeId: event.assignee_id
      };
    });
  },

  /**
   * Create a new event
   */
  async createEvent(workspaceId: string, userId: string, event: Omit<CalendarEvent, 'id'>) {
    const dbPayload = {
      workspace_id: workspaceId,
      user_id: userId,
      title: event.title,
      start_time: event.startTime.toISOString(),
      end_time: event.endTime.toISOString(),
      team_id: event.teamId || null,
      assignee_id: event.assigneeId || null,
      metadata: {
        description: event.description || '',
        category: event.category,
        location: event.location || '',
        isAllDay: event.isAllDay || false,
        attendees: event.attendees || []
      }
    };

    const { data, error } = await supabase
      .from('events')
      .insert(dbPayload)
      .select()
      .single();

    if (error) throw new Error(error.message);
    return data;
  },

  /**
   * Update an existing event
   */
  async updateEvent(eventId: string, updates: Partial<CalendarEvent>) {
    const dbPayload: Record<string, unknown> = {};
    if (updates.title) dbPayload.title = updates.title;
    if (updates.startTime) dbPayload.start_time = updates.startTime.toISOString();
    if (updates.endTime) dbPayload.end_time = updates.endTime.toISOString();
    if (updates.teamId !== undefined) dbPayload.team_id = updates.teamId || null;
    if (updates.assigneeId !== undefined) dbPayload.assignee_id = updates.assigneeId || null;

    // Handle metadata updates if needed
    if (
      updates.description !== undefined || 
      updates.category !== undefined || 
      updates.location !== undefined ||
      updates.isAllDay !== undefined ||
      updates.attendees !== undefined
    ) {
      // First get current metadata to merge
      const { data: current } = await supabase.from('events').select('metadata').eq('id', eventId).single();
      const currentMeta = (current?.metadata as unknown as EventMetadata) || {};
      dbPayload.metadata = {
        ...currentMeta,
        description: updates.description ?? currentMeta.description,
        category: updates.category ?? currentMeta.category,
        location: updates.location ?? currentMeta.location,
        isAllDay: updates.isAllDay ?? currentMeta.isAllDay,
        attendees: updates.attendees ?? currentMeta.attendees
      };
    }

    const { error } = await supabase
      .from('events')
      .update(dbPayload)
      .eq('id', eventId);

    if (error) throw new Error(error.message);
  },

  /**
   * Delete an event
   */
  async deleteEvent(eventId: string) {
    const { error } = await supabase
      .from('events')
      .delete()
      .eq('id', eventId);

    if (error) throw new Error(error.message);
  }
};
